<#
.SYNOPSIS
    Windows 11 Security Scanner - Standalone single-file script.

.DESCRIPTION
    Automatically generated by tools/Build.ps1.
    Bundles the catalog, scan engine, 62 read-only security checks, and WPF/TUI interface.
    Can be executed from any folder or directly from GitHub:
      irm https://raw.githubusercontent.com/elvys9/Powershell-Vulnerability-Scanner/main/dist/scanner-win11-en.ps1 | iex
#>

Set-StrictMode -Version 2
$ErrorActionPreference = 'Stop'
$script:VERSIONE_TOOL = '0.2.0'
$script:LinguaPredefinita = 'EN'
$script:PercorsoScriptAutonomo = [string](Get-Variable -Name PSCommandPath -ValueOnly -ErrorAction SilentlyContinue)
$script:UrlScriptRemoto = 'https://raw.githubusercontent.com/elvys9/Powershell-Vulnerability-Scanner/main/dist/scanner-win11-en.ps1'

# --- EMBEDDED JSON CATALOG ---
$script:CatalogoJsonIncorporato = @'
