      "title": "Windows Firewall active on all profiles",
      "category": "Firewall",
      "severity": "critico",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that Windows Defender Firewall is enabled across Domain, Private, and Public profiles with DefaultInboundAction set to Block.",
      "rationale": "The firewall is the first line of defense against unauthorized inbound connections. Disabling it exposes the system to network-based attacks.",
      "check": {
        "command_ref": "Firewall.ps1#Test-FirewallProfiles"
