      "description": "Audits non-Microsoft Scheduled Tasks for executions from Temp/Public folders or obfuscated PowerShell/LOLBin commands.",
      "rationale": "Malware frequently abuses Windows Scheduled Tasks to maintain persistent background execution at logon or on recurring timers.",
      "check": {
        "command_ref": "FileSecurity.ps1#Test-TaskPianificatiSospetti"
      },
      "references": [
        "MITRE ATT&CK T1053.005 - Scheduled Task/Job"
      ]
    },
    {
      "id": "HOME-FIL-005",
      "title": "No system executable hijacking (IFEO Debugger Hijacking)",
      "category": "File Security",
      "severity": "critico",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that no critical system or accessibility executable (sethc.exe, utilman.exe, taskmgr.exe, MsMpEng.exe) has a Debugger value in Image File Execution Options.",
      "rationale": "Attackers abuse IFEO Debugger hijacking to install login-screen backdoors (Sticky Keys) or block security tools such as Task Manager and Defender.",
      "check": {
        "command_ref": "FileSecurity.ps1#Test-HijackingIFEO"
      },
      "references": [
        "MITRE ATT&CK T1546.012 - Image File Execution Options Injection"
      ]
    },
    {
      "id": "HOME-FIL-006",
      "title": "No suspicious scripts or executables in Startup folders",
      "category": "File Security",
      "severity": "alto",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Scans user and system Startup folders for suspicious scripts or executables (.vbs, .js, .bat, .cmd, .ps1, .hta, .scr).",
      "rationale": "Any script or executable placed in the Startup folder is automatically launched every time a user signs in.",
      "check": {
        "command_ref": "FileSecurity.ps1#Test-CartellaStartupUtente"
      },
      "references": [
        "MITRE ATT&CK T1547.001 - Registry Run Keys / Startup Folder"
      ]
    },
    {
      "id": "HOME-ACC-004",
      "title": "Account lockout policy enabled against brute-force attacks",
      "category": "Accounts",
      "severity": "alto",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that the Account Lockout Threshold is configured between 1 and 10 failed logon attempts.",
      "rationale": "Without an account lockout threshold, an attacker or malware on the local network can perform unlimited password-guessing attempts.",
      "check": {
        "command_ref": "Accounts.ps1#Test-PoliticaBloccoAccount"
      },
      "references": [
        "CIS Benchmark Windows 11 - 1.2.2"
      ]
    },
    {
      "id": "HOME-ACC-005",
      "title": "Minimal number of local Administrators group members (<= 2)",
      "category": "Accounts",
      "severity": "medio",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that the local Administrators group (SID S-1-5-32-544) contains no more than 2 enabled accounts.",
      "rationale": "Minimizing accounts with administrative privileges reduces the attack surface and limits blast radius in the event of account compromise.",
      "check": {
        "command_ref": "Accounts.ps1#Test-LimiteAmministratoriLocali"
      },
      "references": [
        "Principle of Least Privilege"
      ]
    },
    {
      "id": "HOME-NET-004",
      "title": "No non-standard SMB network shares exposed",
      "category": "Network",
      "severity": "alto",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that no user-defined SMB shares are exposed on the local network beyond default administrative shares.",
      "rationale": "Exposed local network shares can be abused by ransomware or untrusted devices on the same Wi-Fi network to read or encrypt files.",
      "check": {
        "command_ref": "Network.ps1#Test-CondivisioniSmbPericolose"
      },
      "references": [
        "MITRE ATT&CK T1135 - Network Share Discovery"
      ]
    },
    {
      "id": "HOME-NET-005",
      "title": "Mandatory SMB digital signing enabled (anti-NTLM Relay)",
      "category": "Network",
      "severity": "alto",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that RequireSecuritySignature = 1 is enforced for both SMB Server and SMB Client.",
      "rationale": "Mandatory SMB packet signing prevents local network attackers from intercepting and relaying credentials via SMB/NTLM Relay attacks.",
      "check": {
        "command_ref": "Network.ps1#Test-FirmaSmbObbligatoria"
      },
      "references": [
        "CIS Benchmark Windows 11 - 2.3.8.1 / 2.3.9.2"
      ]
    },
    {
      "id": "HOME-NET-006",
      "title": "Windows Remote Management (WinRM / PowerShell Remoting) disabled",
      "category": "Network",
      "severity": "alto",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that the WinRM service is stopped so remote administration ports 5985/5986 are not exposed.",
      "rationale": "On personal desktops and laptops, WinRM exposes a remote PowerShell execution endpoint frequently abused for lateral movement.",
      "check": {
        "command_ref": "Network.ps1#Test-WinRmDisabilitatoOSicuro"
      },
      "references": [
        "CIS Benchmark Windows 11 - 18.9.102.2"
      ]
    },
    {
      "id": "HOME-NET-007",
      "title": "WPAD automatic web proxy discovery disabled (anti-MITM)",
      "category": "Network",
      "severity": "medio",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that Web Proxy Auto-Discovery (WPAD) is disabled in the registry or via the WinHttpAutoProxySvc service.",
      "rationale": "An attacker on the same LAN or Wi-Fi network can spoof WPAD responses to intercept and proxy all web traffic from the machine.",
      "check": {
        "command_ref": "Network.ps1#Test-WpadDisabilitato"
      },
      "references": [
        "MITRE ATT&CK T1557.001 - LLMNR/NBT-NS/WPAD Poisoning"
      ]
    },
    {
      "id": "HOME-SYS-006",
      "title": "WDigest credential protection (no cleartext passwords in memory)",
      "category": "Windows Settings",
      "severity": "medio",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Anti-tampering check verifying that WDigest UseLogonCredential is set to 0 (or absent) to prevent cleartext password caching in LSASS.",
      "rationale": "If an attacker sets WDigest UseLogonCredential to 1, Windows caches user passwords in plaintext in RAM, enabling credential theft.",
      "check": {
        "command_ref": "SystemSecurity.ps1#Test-WDigestDisabilitato"
      },
      "references": [
        "CIS Benchmark Windows 11 - 18.4.8"
      ]
    },
    {
      "id": "HOME-SYS-007",
      "title": "Windows Remote Assistance disabled",
      "category": "Windows Settings",
      "severity": "medio",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that fAllowToGetHelp is set to 0 in the Remote Assistance registry key.",
      "rationale": "Disabling Remote Assistance reduces the risk of unauthorized remote support connections to the computer.",
      "check": {
        "command_ref": "SystemSecurity.ps1#Test-AssistenzaRemotaDisabilitata"
      },
      "references": [
        "CIS Benchmark Windows 11 - 18.9.65.2"
      ]
    },
    {
      "id": "HOME-SYS-008",
      "title": "Remote Registry service disabled",
      "category": "Windows Settings",
      "severity": "alto",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that the RemoteRegistry service is disabled (Start = 4) and not running.",
      "rationale": "The Remote Registry service allows remote reading and modification of the Windows registry over the network.",
      "check": {
        "command_ref": "SystemSecurity.ps1#Test-RegistroRemotoDisabilitato"
      },
      "references": [
        "CIS Benchmark Windows 11 - 5.27"
      ]
    },
    {
      "id": "HOME-SEC-006",
      "title": "Microsoft Vulnerable Driver Blocklist (anti-BYOVD) enabled",
      "category": "Advanced Security",
      "severity": "alto",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that Microsoft's Vulnerable Driver Blocklist (VulnerableDriverBlocklistEnable = 1) is enabled in CI\\Config.",
      "rationale": "Prevents loading signed drivers with known vulnerabilities abused in Bring Your Own Vulnerable Driver (BYOVD) attacks to disable EDR/Defender in the kernel.",
      "check": {
        "registry": {
          "path": "HKLM:\\SYSTEM\\CurrentControlSet\\Control\\CI\\Config",
          "name": "VulnerableDriverBlocklistEnable",
          "operator": "eq",
          "value": 1
        }
      },
      "references": [
        "Microsoft Security Baseline Windows 11 - Driver Block Rules",
        "MITRE ATT&CK T1068 - Exploitation for Privilege Escalation (BYOVD)"
      ]
    },
    {
      "id": "HOME-SEC-007",
      "title": "Smart App Control (SAC) active",
      "category": "Advanced Security",
      "severity": "medio",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies Smart App Control status (VerifiedAndReputablePolicyState = 1 Enforced or 2 Evaluation) in Control\\CI\\Policy.",
      "rationale": "Smart App Control blocks untrusted, unsigned, or potentially malicious applications at the OS level on Windows 11.",
      "check": {
        "command_ref": "SystemSecurity.ps1#Test-SmartAppControl"
      },
      "references": [
        "Microsoft Windows 11 Security - Smart App Control",
        "Harden-Windows-Security Baseline"
      ]
    },
    {
      "id": "HOME-AV-011",
      "title": "Microsoft Defender Attack Surface Reduction (ASR) rules active",
      "category": "Antivirus",
      "severity": "alto",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies via Get-MpPreference that ASR rules are configured in Block (1) or Warn (6) mode, including LSASS credential theft protection and obfuscated script blocking.",
      "rationale": "ASR rules block common ransomware and fileless malware techniques such as LSASS credential dumping, malicious Office macros, and obfuscated scripts.",
      "check": {
        "command_ref": "Defender.ps1#Test-DefenderAsrRules"
      },
      "references": [
        "CIS Benchmark Windows 11 - 18.9.47.5",
        "Microsoft Defender Exploit Guard - Attack Surface Reduction"
      ]
    },
    {
      "id": "HOME-SEC-008",
      "title": "Hardware security chip TPM 2.0 present and ready",
      "category": "Advanced Security",
      "severity": "alto",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies via Get-Tpm (or Win32_Tpm) that a TPM 2.0 module is present and ready for use (TpmPresent = True, TpmReady = True).",
      "rationale": "TPM 2.0 provides the hardware root of trust required by BitLocker, Windows Hello, Secure Boot, and Credential Guard.",
      "check": {
        "command_ref": "SystemSecurity.ps1#Test-Tpm20Ready"
      },
      "references": [
        "Microsoft Windows 11 Hardware Security Baseline - TPM 2.0"
      ]
    },
    {
      "id": "HOME-NET-008",
      "title": "Legacy TLS 1.0/1.1 disabled and DNS over HTTPS (DoH) supported",
      "category": "Network",
      "severity": "medio",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that TLS 1.0 and TLS 1.1 are not forced enabled in SCHANNEL and that the DNS client supports DNS over HTTPS (DoH).",
      "rationale": "Disabling TLS 1.0/1.1 prevents cryptographic downgrade attacks (BEAST/POODLE), while DNS over HTTPS encrypts DNS queries against interception and spoofing.",
      "check": {
        "command_ref": "Network.ps1#Test-LegacyTlsAndDoh"
      },
      "references": [
        "IETF RFC 8996 - Deprecating TLS 1.0 and TLS 1.1",
        "IETF RFC 8484 - DNS Queries over HTTPS (DoH)"
      ]
    },
    {
      "id": "HOME-SYS-009",
      "title": "Windows Script Host (WSH) disabled against malicious .vbs/.js scripts",
      "category": "Windows Settings",
      "severity": "medio",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that Windows Script Host (wscript.exe/cscript.exe) is disabled by setting Enabled = 0 in Windows Script Host\\Settings.",
      "rationale": "Disabling WSH blocks automatic execution of VBScript (.vbs/.vbe) and JScript (.js/.jse) droppers commonly delivered via phishing campaigns.",
      "check": {
        "command_ref": "SystemSecurity.ps1#Test-WshDisabled"
      },
      "references": [
        "HardeningKitty - Windows Script Host Hardening",
        "MITRE ATT&CK T1059.005 / T1059.007"
      ]
    },
    {
      "id": "HOME-SEC-009",
      "title": "Secure PowerShell ExecutionPolicy (no Unrestricted or Bypass scopes)",
      "category": "Advanced Security",
      "severity": "medio",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies via Get-ExecutionPolicy -List that no persistent scope (MachinePolicy, UserPolicy, LocalMachine, CurrentUser) is set to Unrestricted or Bypass.",
      "rationale": "An overly permissive ExecutionPolicy allows unsigned or Internet-downloaded PowerShell scripts to run without restriction.",
      "check": {
        "command_ref": "SystemSecurity.ps1#Test-PowerShellExecutionPolicySecure"
      },
      "references": [
        "Microsoft PowerShell Security Best Practices",
        "HardeningKitty - PowerShell Execution Policy"
      ]
    },
    {
      "id": "HOME-UAC-004",
      "title": "Windows 11 Administrator Protection (JIT) active",
      "category": "UAC",
      "severity": "medio",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that Windows 11 24H2/25H2/26H2 just-in-time Administrator Protection is enabled via TypeOfAdminApprovalMode = 2 in Policies\\System.",
      "rationale": "Administrator Protection creates a separate hidden admin account with just-in-time elevation tokens, preventing malware from silently inheriting a standing admin token.",
      "check": {
        "command_ref": "SystemSecurity.ps1#Test-AdministratorProtection"
      },
      "references": [
        "Microsoft Security Baseline Windows 11 25H2/26H2 - Administrator Protection"
      ]
    },
    {
      "id": "HOME-FIL-007",
      "title": "No fileless persistence via WMI Event Subscriptions",
      "category": "File Security",
      "severity": "critico",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Queries the root\\subscription namespace in read-only mode to ensure no suspicious CommandLineEventConsumer, ActiveScriptEventConsumer, or EventFilter objects exist.",
      "rationale": "Attackers abuse permanent WMI event subscriptions to achieve stealthy fileless persistence outside standard Run keys, executing scripts or commands on system events.",
      "check": {
        "command_ref": "FileSecurity.ps1#Test-WmiEventSubscriptions"
      },
      "references": [
        "MITRE ATT&CK T1546.003 - Windows Management Instrumentation Event Subscription"
      ]
    },
    {
      "id": "HOME-FIL-008",
      "title": "No policy-forced browser extensions (Chrome / Edge)",
      "category": "File Security",
      "severity": "alto",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that ExtensionInstallForcelist registry keys in HKLM/HKCU for Google Chrome and Microsoft Edge do not contain forced extensions.",
      "rationale": "Malware, adware, and infostealers often force silent installation of malicious browser extensions via ExtensionInstallForcelist, preventing users from removing them via the browser UI.",
      "check": {
        "command_ref": "FileSecurity.ps1#Test-BrowserForcedExtensions"
      },
      "references": [
        "MITRE ATT&CK T1176 - Browser Extensions"
      ]
    },
    {
      "id": "HOME-SEC-010",
      "title": "Windows Event Log integrity and no recent Security log clearing (Event ID 1102)",
      "category": "Advanced Security",
      "severity": "alto",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that the Windows Event Log service (EventLog) is running and queries the Security event log for log-clearing events (Event ID 1102) in the last 30 days.",
      "rationale": "Attackers frequently stop the Event Log service or clear the Security log (Event ID 1102) to hide intrusion evidence and evade forensic investigation.",
      "check": {
        "command_ref": "SystemSecurity.ps1#Test-EventLogIntegrity"
      },
      "references": [
        "MITRE ATT&CK T1070.001 - Clear Windows Event Logs",
        "CIS Benchmark Windows 11 - Event Log Service"
      ]
    },
    {
      "id": "HOME-SYS-010",
      "title": "PrintNightmare printer driver installation protection enabled",
      "category": "Windows Settings",
      "severity": "alto",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Verifies that the Print Spooler service is disabled or that Point and Print driver installation is not overridden via RestrictDriverInstallationToAdministrators = 0.",
      "rationale": "Allowing non-administrators to install printer drivers via Point and Print exposes Windows to PrintNightmare (CVE-2021-34527) local privilege escalation and remote code execution.",
      "check": {
        "command_ref": "SystemSecurity.ps1#Test-PrintNightmareProtection"
      },
      "references": [
        "Microsoft CVE-2021-34527 - PrintNightmare Mitigation",
        "Microsoft Security Baseline Windows 11"
      ]
    },
    {
      "id": "HOME-FIL-009",
      "title": "No vulnerable unquoted service executable paths",
      "category": "File Security",
      "severity": "alto",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Audits registered Windows services (Win32_Service) for third-party executable paths containing spaces that are not enclosed in quotation marks.",
      "rationale": "Unquoted service paths containing spaces outside SystemRoot allow local privilege escalation by placing a malicious executable earlier in Windows path resolution order.",
      "check": {
        "command_ref": "FileSecurity.ps1#Test-UnquotedServicePaths"
      },
      "references": [
        "MITRE ATT&CK T1574.009 - Path Interception by Unquoted Path"
      ]
    },
    {
      "id": "HOME-SEC-011",
      "title": "Kernel DMA Protection enabled against external PCIe/Thunderbolt attacks",
      "category": "Advanced Security",
      "severity": "medio",
      "editions": [
        "Home",
        "Pro"
      ],
      "description": "Queries Win32_DeviceGuard AvailableSecurityProperties for hardware Kernel DMA Protection support and verifies it is not disabled via DeviceEnumerationPolicy = 2.",
      "rationale": "Kernel DMA Protection leverages hardware IOMMU isolation to block rogue external PCIe or Thunderbolt peripherals from performing unauthorized direct memory access.",
      "check": {
        "command_ref": "SystemSecurity.ps1#Test-KernelDmaProtection"
      },
      "references": [
        "Microsoft Secured-core PC - Kernel DMA Protection"
      ]
    }
  ]
}
'@

# --- EMBEDDED XAML LAYOUT ---
$script:XamlIncorporato = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Windows 11 Security Scanner (Read-Only)"
        Width="1280"
        Height="860"
        MinWidth="1040"
        MinHeight="700"
        WindowStartupLocation="CenterScreen"
        FontFamily="Segoe UI"
        FontSize="13"
        SnapsToDevicePixels="True"
        UseLayoutRounding="True"
        TextOptions.TextFormattingMode="Display"
        TextOptions.TextRenderingMode="ClearType"
        Background="{DynamicResource BgPrimary}"
        Foreground="{DynamicResource TextPrimary}">

    <Window.Resources>
        <!-- Palette predefinita (Tema Scuro Moderno Fluent - aggiornabile a caldo in Chiaro/Scuro) -->
        <SolidColorBrush x:Key="BgPrimary" Color="#0B0F19"/>
        <SolidColorBrush x:Key="BgSurface" Color="#111827"/>
        <SolidColorBrush x:Key="BgElevated" Color="#1E293B"/>
        <SolidColorBrush x:Key="BgHeader" Color="#060911"/>
        <SolidColorBrush x:Key="TextHeader" Color="#F8FAFC"/>
        <SolidColorBrush x:Key="BgSubtle" Color="#0F172A"/>
        <SolidColorBrush x:Key="BgInput" Color="#0F172A"/>
        <SolidColorBrush x:Key="BgAlternating" Color="#131C2E"/>
        <SolidColorBrush x:Key="SelectedRowBg" Color="#1E3A8A"/>
        <SolidColorBrush x:Key="SelectedRowFg" Color="#FFFFFF"/>
        <SolidColorBrush x:Key="HoverRowBg" Color="#1E293B"/>
        <SolidColorBrush x:Key="TextPrimary" Color="#F1F5F9"/>
        <SolidColorBrush x:Key="TextSecondary" Color="#94A3B8"/>
        <SolidColorBrush x:Key="BorderSubtle" Color="#1E293B"/>
        <SolidColorBrush x:Key="BorderStrong" Color="#334155"/>
        <SolidColorBrush x:Key="AccentBrush" Color="#3B82F6"/>
        <SolidColorBrush x:Key="AccentText" Color="#FFFFFF"/>

        <!-- Colori semantici per i 5 stati -->
        <SolidColorBrush x:Key="PassBg" Color="#064E3B"/>
        <SolidColorBrush x:Key="PassFg" Color="#6EE7B7"/>
        <SolidColorBrush x:Key="PassBorder" Color="#10B981"/>

        <SolidColorBrush x:Key="FailBg" Color="#7F1D1D"/>
        <SolidColorBrush x:Key="FailFg" Color="#FCA5A5"/>
        <SolidColorBrush x:Key="FailBorder" Color="#EF4444"/>

        <SolidColorBrush x:Key="UnknownBg" Color="#1E293B"/>
        <SolidColorBrush x:Key="UnknownFg" Color="#CBD5E1"/>
        <SolidColorBrush x:Key="UnknownBorder" Color="#64748B"/>

        <SolidColorBrush x:Key="NaBg" Color="#0F172A"/>
        <SolidColorBrush x:Key="NaFg" Color="#94A3B8"/>
        <SolidColorBrush x:Key="NaBorder" Color="#475569"/>

        <SolidColorBrush x:Key="ErrorBg" Color="#7C2D12"/>
        <SolidColorBrush x:Key="ErrorFg" Color="#FDBA74"/>
        <SolidColorBrush x:Key="ErrorBorder" Color="#F97316"/>

        <SolidColorBrush x:Key="WarnBannerBg" Color="#451A03"/>
        <SolidColorBrush x:Key="WarnBannerFg" Color="#FDE68A"/>
        <SolidColorBrush x:Key="WarnBannerBorder" Color="#D97706"/>

        <!-- Stile Moderno per tutti i Pulsanti con bordi arrotondati -->
        <Style x:Key="ModernButton" TargetType="Button">
            <Setter Property="Background" Value="{DynamicResource BgElevated}"/>
            <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
            <Setter Property="BorderBrush" Value="{DynamicResource BorderStrong}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Padding" Value="14,7"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border"
                                Background="{TemplateBinding Background}"
                                BorderBrush="{TemplateBinding BorderBrush}"
                                BorderThickness="{TemplateBinding BorderThickness}"
                                CornerRadius="6"
                                Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Center"
                                              VerticalAlignment="Center"
                                              RecognizesAccessKey="True"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="border" Property="Opacity" Value="0.88"/>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="border" Property="Opacity" Value="0.74"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="border" Property="Opacity" Value="0.38"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Stile TextBox compatibile con Dark e Light Theme -->
        <Style TargetType="TextBox">
            <Setter Property="Background" Value="{DynamicResource BgInput}"/>
            <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
            <Setter Property="CaretBrush" Value="{DynamicResource TextPrimary}"/>
            <Setter Property="BorderBrush" Value="{DynamicResource BorderStrong}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="SelectionBrush" Value="{DynamicResource AccentBrush}"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="TextBox">
                        <Border x:Name="Bd"
                                Background="{TemplateBinding Background}"
                                BorderBrush="{TemplateBinding BorderBrush}"
                                BorderThickness="{TemplateBinding BorderThickness}"
                                CornerRadius="6"
                                Padding="{TemplateBinding Padding}">
                            <ScrollViewer x:Name="PART_ContentHost" Focusable="False" HorizontalScrollBarVisibility="Hidden" VerticalScrollBarVisibility="Hidden"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsKeyboardFocused" Value="True">
                                <Setter TargetName="Bd" Property="BorderBrush" Value="{DynamicResource AccentBrush}"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Stile ComboBoxItem compatibile con Dark e Light Theme -->
        <Style TargetType="ComboBoxItem">
            <Setter Property="Background" Value="{DynamicResource BgElevated}"/>
            <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
            <Setter Property="Padding" Value="10,6"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ComboBoxItem">
                        <Border x:Name="Bd"
                                Background="{TemplateBinding Background}"
                                Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Left" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsHighlighted" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="{DynamicResource SelectedRowBg}"/>
                                <Setter Property="Foreground" Value="{DynamicResource SelectedRowFg}"/>
                            </Trigger>
                            <Trigger Property="IsSelected" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="{DynamicResource SelectedRowBg}"/>
                                <Setter Property="Foreground" Value="{DynamicResource SelectedRowFg}"/>
                                <Setter Property="FontWeight" Value="SemiBold"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Stile ComboBox completamente personalizzato per Dark e Light Theme -->
        <Style TargetType="ComboBox">
            <Setter Property="Background" Value="{DynamicResource BgInput}"/>
            <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
            <Setter Property="BorderBrush" Value="{DynamicResource BorderStrong}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Padding" Value="10,4"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ComboBox">
                        <Grid>
                            <ToggleButton x:Name="ToggleButton"
                                          Focusable="False"
                                          IsChecked="{Binding IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}"
                                          ClickMode="Press"
                                          Background="{TemplateBinding Background}"
                                          BorderBrush="{TemplateBinding BorderBrush}"
                                          BorderThickness="{TemplateBinding BorderThickness}">
                                <ToggleButton.Template>
                                    <ControlTemplate TargetType="ToggleButton">
                                        <Border x:Name="Border"
                                                Background="{TemplateBinding Background}"
                                                BorderBrush="{TemplateBinding BorderBrush}"
                                                BorderThickness="{TemplateBinding BorderThickness}"
                                                CornerRadius="6">
                                            <Grid>
                                                <Grid.ColumnDefinitions>
                                                    <ColumnDefinition Width="*"/>
                                                    <ColumnDefinition Width="26"/>
                                                </Grid.ColumnDefinitions>
                                                <Path Grid.Column="1"
                                                      HorizontalAlignment="Center"
                                                      VerticalAlignment="Center"
                                                      Data="M 0 0 L 4 4 L 8 0 Z"
                                                      Fill="{DynamicResource TextSecondary}"/>
                                            </Grid>
                                        </Border>
                                        <ControlTemplate.Triggers>
                                            <Trigger Property="IsMouseOver" Value="True">
                                                <Setter TargetName="Border" Property="BorderBrush" Value="{DynamicResource AccentBrush}"/>
                                            </Trigger>
                                        </ControlTemplate.Triggers>
                                    </ControlTemplate>
                                </ToggleButton.Template>
                            </ToggleButton>

                            <ContentPresenter x:Name="ContentSite"
                                              IsHitTestVisible="False"
                                              Content="{TemplateBinding SelectionBoxItem}"
                                              ContentTemplate="{TemplateBinding SelectionBoxItemTemplate}"
                                              ContentTemplateSelector="{TemplateBinding ItemTemplateSelector}"
                                              Margin="10,3,26,3"
                                              VerticalAlignment="Center"
                                              HorizontalAlignment="Left"/>

                            <TextBox x:Name="PART_EditableTextBox"
                                     Visibility="Hidden"
                                     IsReadOnly="{TemplateBinding IsReadOnly}"
                                     Background="Transparent"
                                     Foreground="{DynamicResource TextPrimary}"
                                     CaretBrush="{DynamicResource TextPrimary}"
                                     BorderThickness="0"
                                     Margin="8,3,26,3"
                                     VerticalAlignment="Center"
                                     HorizontalAlignment="Stretch"
                                     Focusable="True"/>

                            <Popup x:Name="Popup"
                                   Placement="Bottom"
                                   IsOpen="{TemplateBinding IsDropDownOpen}"
                                   AllowsTransparency="True"
                                   Focusable="False"
                                   PopupAnimation="Slide">
                                <Grid x:Name="DropDown"
                                      SnapsToDevicePixels="True"
                                      MinWidth="{TemplateBinding ActualWidth}"
                                      MaxHeight="{TemplateBinding MaxDropDownHeight}">
                                    <Border x:Name="DropDownBorder"
                                            Background="{DynamicResource BgElevated}"
                                            BorderBrush="{DynamicResource BorderStrong}"
                                            BorderThickness="1"
                                            CornerRadius="6"
                                            Margin="0,2,0,0">
                                        <ScrollViewer Margin="2" SnapsToDevicePixels="True">
                                            <StackPanel IsItemsHost="True" KeyboardNavigation.DirectionalNavigation="Contained"/>
                                        </ScrollViewer>
                                    </Border>
                                </Grid>
                            </Popup>
                        </Grid>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsEditable" Value="True">
                                <Setter Property="IsTabStop" Value="False"/>
                                <Setter TargetName="PART_EditableTextBox" Property="Visibility" Value="Visible"/>
                                <Setter TargetName="ContentSite" Property="Visibility" Value="Hidden"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Stile DataGridColumnHeader per Dark e Light Theme -->
        <Style TargetType="DataGridColumnHeader">
            <Setter Property="Background" Value="{DynamicResource BgSubtle}"/>
            <Setter Property="Foreground" Value="{DynamicResource TextSecondary}"/>
            <Setter Property="BorderBrush" Value="{DynamicResource BorderSubtle}"/>
            <Setter Property="BorderThickness" Value="0,0,1,1"/>
            <Setter Property="Padding" Value="12,9"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="FontSize" Value="11.5"/>
            <Setter Property="HorizontalContentAlignment" Value="Left"/>
        </Style>

        <!-- Stile DataGridRow e DataGridCell per selezione nitida in Dark e Light Theme -->
        <Style TargetType="DataGridRow">
            <Setter Property="Background" Value="{DynamicResource BgSurface}"/>
            <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Style.Triggers>
                <Trigger Property="ItemsControl.AlternationIndex" Value="1">
                    <Setter Property="Background" Value="{DynamicResource BgAlternating}"/>
                </Trigger>
                <Trigger Property="IsMouseOver" Value="True">
                    <Setter Property="Background" Value="{DynamicResource HoverRowBg}"/>
                </Trigger>
                <Trigger Property="IsSelected" Value="True">
                    <Setter Property="Background" Value="{DynamicResource SelectedRowBg}"/>
                    <Setter Property="Foreground" Value="{DynamicResource SelectedRowFg}"/>
                </Trigger>
            </Style.Triggers>
        </Style>

        <Style TargetType="DataGridCell">
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Padding" Value="10,4"/>
            <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="DataGridCell">
                        <Border Background="{TemplateBinding Background}"
                                BorderThickness="0"
                                Padding="{TemplateBinding Padding}"
                                SnapsToDevicePixels="True">
                            <ContentPresenter VerticalAlignment="Center"/>
                        </Border>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
            <Style.Triggers>
                <Trigger Property="IsSelected" Value="True">
                    <Setter Property="Background" Value="{DynamicResource SelectedRowBg}"/>
                    <Setter Property="Foreground" Value="{DynamicResource SelectedRowFg}"/>
                </Trigger>
            </Style.Triggers>
        </Style>
    </Window.Resources>

    <Grid>
        <Grid.RowDefinitions>
            <!-- 0: Intestazione principale (Brand + Selettore Lingua 3 pulsanti + Tema + OS Info) -->
            <RowDefinition Height="Auto"/>
            <!-- 1: Banner avviso non-amministratore / errore -->
            <RowDefinition Height="Auto"/>
            <!-- 2: Barra Navigazione Schede (Tab 1 / Tab 2) + Azioni Scansione e Progresso -->
            <RowDefinition Height="Auto"/>
            <!-- 3: 5 Card KPI contatori stato -->
            <RowDefinition Height="Auto"/>
            <!-- 4: Corpo principale (Pagina 1: Tabella + Dettaglio / Pagina 2: Assistente IA Ollama) -->
            <RowDefinition Height="*"/>
            <!-- 5: Footer con Export e Disclaimer permanente -->
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

        <!-- ================= RIGA 0: INTESTAZIONE ================= -->
        <Border Grid.Row="0"
                Background="{DynamicResource BgHeader}"
                BorderBrush="{DynamicResource BorderSubtle}"
                BorderThickness="0,0,0,1"
                Padding="20,12">
            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>

                <!-- Colonna 0: Logo e Titolo -->
                <StackPanel Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center">
                    <Border Background="#1D4ED8" CornerRadius="8" Width="38" Height="38" Margin="0,0,12,0" VerticalAlignment="Center">
                        <Canvas Width="20" Height="20" HorizontalAlignment="Center" VerticalAlignment="Center">
                            <Path Data="M6,9 V6 A4,4 0 0,1 14,6 V9 M4,9 H16 A1,1 0 0,1 17,10 V17 A1,1 0 0,1 16,18 H4 A1,1 0 0,1 3,17 V10 A1,1 0 0,1 4,9 Z"
                                  Stroke="#FFFFFF" StrokeThickness="1.8" StrokeLineJoin="Round"/>
                        </Canvas>
                    </Border>
                    <StackPanel VerticalAlignment="Center">
                        <StackPanel Orientation="Horizontal">
                            <TextBlock x:Name="TxtTitoloApp"
                                       Text="Scanner Sicurezza Windows 11"
                                       FontSize="18"
                                       FontWeight="Bold"
                                       Foreground="{DynamicResource TextHeader}"
                                       VerticalAlignment="Center"/>
                            <Border Background="#065F46" BorderBrush="#10B981" BorderThickness="1" CornerRadius="5" Padding="8,2" Margin="10,0,0,0" VerticalAlignment="Center">
                                <TextBlock x:Name="TxtBadgeSolaLettura"
                                           Text="SOLA LETTURA"
                                           FontSize="10"
                                           FontWeight="Bold"
                                           Foreground="#A7F3D0"/>
                            </Border>
                        </StackPanel>
                        <TextBlock x:Name="TxtSottotitoloApp"
                                   Text="62 Controlli Deterministici + Assistente IA Locale (Ollama)"
                                   FontSize="11.5"
                                   Foreground="#94A3B8"
                                   Margin="0,2,0,0"/>
                    </StackPanel>
                </StackPanel>

                <!-- Colonna 1: Info OS + Selettore Lingua esplicito [IT | EN | DE] + Pulsante Tema -->
                <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">
                    <!-- Badge Sistema Operativo -->
                    <Border Background="#111827"
                            BorderBrush="#334155"
                            BorderThickness="1"
                            CornerRadius="6"
                            Padding="11,6"
                            Margin="0,0,10,0"
                            VerticalAlignment="Center">
                        <TextBlock x:Name="TxtAmbienteInfo"
                                   Text="Windows 11 | Admin: No"
                                   FontSize="11.5"
                                   FontWeight="SemiBold"
                                   Foreground="#E2E8F0"/>
                    </Border>

                    <!-- Selettore Lingua Esplicito a 3 pulsanti (mostra chiaramente la lingua attiva) -->
                    <Border Background="#111827"
                            BorderBrush="#334155"
                            BorderThickness="1"
                            CornerRadius="7"
                            Padding="3"
                            Margin="0,0,10,0"
                            VerticalAlignment="Center">
                        <StackPanel Orientation="Horizontal">
                            <TextBlock x:Name="LblLinguaAttiva"
                                       Text="Lingua:"
                                       FontSize="11"
                                       FontWeight="SemiBold"
                                       Foreground="#94A3B8"
                                       VerticalAlignment="Center"
                                       Margin="7,0,6,0"/>
                            <Button x:Name="BtnLinguaIT"
                                    Style="{StaticResource ModernButton}"
                                    Content="IT Italiano"
                                    Padding="9,4"
                                    Margin="0,0,3,0"
                                    FontSize="11.5"
                                    FontWeight="Bold"
                                    Background="#2563EB"
                                    Foreground="#FFFFFF"
                                    BorderThickness="0"/>
                            <Button x:Name="BtnLinguaEN"
                                    Style="{StaticResource ModernButton}"
                                    Content="EN English"
                                    Padding="9,4"
                                    Margin="0,0,3,0"
                                    FontSize="11.5"
                                    FontWeight="SemiBold"
                                    Background="Transparent"
                                    Foreground="#94A3B8"
                                    BorderThickness="0"/>
                            <Button x:Name="BtnLinguaDE"
                                    Style="{StaticResource ModernButton}"
                                    Content="DE Deutsch"
                                    Padding="9,4"
                                    FontSize="11.5"
                                    FontWeight="SemiBold"
                                    Background="Transparent"
                                    Foreground="#94A3B8"
                                    BorderThickness="0"/>
                            <!-- Alias nascosto per retrocompatibilita' -->
                            <Button x:Name="BtnLingua" Visibility="Collapsed"/>
                        </StackPanel>
                    </Border>

                    <!-- Pulsante Tema con indicazione chiara del tema attivo -->
                    <Button x:Name="BtnTema"
                            Style="{StaticResource ModernButton}"
                            Content="Tema: Scuro"
                            Padding="12,6"
                            FontSize="11.5"
                            FontWeight="SemiBold"
                            Background="#1E293B"
                            Foreground="#F8FAFC"
                            BorderBrush="#475569"/>
                </StackPanel>
            </Grid>
        </Border>

        <!-- ================= RIGA 1: BANNER AVVISI ================= -->
        <StackPanel Grid.Row="1">
            <!-- Banner Non-Amministratore -->
            <Border x:Name="BannerNonAdmin"
                    Visibility="Collapsed"
                    Background="{DynamicResource WarnBannerBg}"
                    BorderBrush="{DynamicResource WarnBannerBorder}"
                    BorderThickness="0,0,0,1"
                    Padding="20,8">
                <Grid>
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="Auto"/>
                    </Grid.ColumnDefinitions>
                    <TextBlock x:Name="TxtBannerNonAdmin"
                               Grid.Column="0"
                               VerticalAlignment="Center"
                               Foreground="{DynamicResource WarnBannerFg}"
                               FontWeight="SemiBold"
                               TextWrapping="Wrap"
                               Text="[!] Sessione non amministrativa: alcuni controlli risulteranno 'Sconosciuto'. Riavvia come Amministratore per l'analisi completa."/>
                    <Button x:Name="BtnRiavviaAdmin"
                            Style="{StaticResource ModernButton}"
                            Grid.Column="1"
                            Content="Riavvia come amministratore"
                            Padding="12,5"
                            Margin="12,0,0,0"
                            FontWeight="SemiBold"/>
                </Grid>
            </Border>

            <!-- Banner Errore Generale -->
            <Border x:Name="BannerErrore"
                    Visibility="Collapsed"
                    Background="{DynamicResource ErrorBg}"
                    BorderBrush="{DynamicResource ErrorBorder}"
                    BorderThickness="0,0,0,1"
                    Padding="20,8">
                <TextBlock x:Name="TxtBannerErrore"
                           Foreground="{DynamicResource ErrorFg}"
                           FontWeight="SemiBold"
                           TextWrapping="Wrap"
                           Text=""/>
            </Border>
        </StackPanel>

        <!-- ================= RIGA 2: BARRA SCHEDE E AZIONI SCANSIONE ================= -->
        <Border Grid.Row="2"
                Background="{DynamicResource BgSurface}"
                BorderBrush="{DynamicResource BorderSubtle}"
                BorderThickness="0,0,0,1"
                Padding="20,10">
            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>

                <!-- Schede di navigazione Pagina 1 / Pagina 2 (mai troncate, evidenziano la scheda attiva) -->
                <Border Grid.Column="0"
                        Background="{DynamicResource BgSubtle}"
                        BorderBrush="{DynamicResource BorderStrong}"
                        BorderThickness="1"
                        CornerRadius="8"
                        Padding="3"
                        Margin="0,0,16,0"
                        VerticalAlignment="Center">
                    <StackPanel Orientation="Horizontal">
                        <Button x:Name="BtnNavScansione"
                                Style="{StaticResource ModernButton}"
                                Content="1. Tabella Controlli &amp; Dettagli"
                                Padding="14,6"
                                Margin="0,0,4,0"
                                FontWeight="Bold"
                                Background="#2563EB"
                                Foreground="#FFFFFF"
                                BorderThickness="0"/>
                        <Button x:Name="BtnNavIA"
                                Style="{StaticResource ModernButton}"
                                Content="2. Assistente IA (Ollama)"
                                Padding="14,6"
                                FontWeight="SemiBold"
                                Background="Transparent"
                                Foreground="{DynamicResource TextSecondary}"
                                BorderThickness="0"/>
                    </StackPanel>
                </Border>

                <!-- Pulsanti Azione Scansione -->
                <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">
                    <Button x:Name="BtnAvvia"
                            Style="{StaticResource ModernButton}"
                            Content="Avvia scansione (34 controlli)"
                            FontWeight="Bold"
                            Padding="16,7"
                            Margin="0,0,8,0"
                            Background="#10B981"
                            Foreground="#FFFFFF"
                            BorderThickness="0"/>

                    <Button x:Name="BtnAnnulla"
                            Style="{StaticResource ModernButton}"
                            Content="Annulla"
                            Padding="12,7"
                            Margin="0,0,8,0"
                            IsEnabled="False"/>

                    <Button x:Name="BtnResocontoLLM"
                            Style="{StaticResource ModernButton}"
                            Content="Apri Resoconto IA &amp; Consigli"
                            FontWeight="Bold"
                            Padding="14,7"
                            Margin="0,0,14,0"
                            Background="#7C3AED"
                            Foreground="#FFFFFF"
                            BorderThickness="0"
                            IsEnabled="False"/>
                </StackPanel>

                <!-- Barra di Progresso arrotondata -->
                <Border Grid.Column="2"
                        CornerRadius="6"
                        Background="{DynamicResource BgSubtle}"
                        BorderBrush="{DynamicResource BorderStrong}"
                        BorderThickness="1"
                        Height="14"
                        VerticalAlignment="Center"
                        Margin="0,0,14,0"
                        ClipToBounds="True">
                    <ProgressBar x:Name="ProgressScansione"
                                 Minimum="0"
                                 Maximum="100"
                                 Value="0"
                                 Background="Transparent"
                                 Foreground="#10B981"
                                 BorderThickness="0"/>
                </Border>

                <TextBlock x:Name="TxtProgresso"
                           Grid.Column="3"
                           VerticalAlignment="Center"
                           Foreground="{DynamicResource TextPrimary}"
                           FontWeight="Bold"
                           FontSize="12.5"
                           Text="Pronto (0/34)"/>
            </Grid>
        </Border>

        <!-- ================= RIGA 3: 5 CARD KPI STATO ================= -->
        <UniformGrid Grid.Row="3" Columns="5" Margin="16,10,16,6">
            <!-- Superati -->
            <Border Background="{DynamicResource PassBg}"
                    BorderBrush="{DynamicResource PassBorder}"
                    BorderThickness="4,1,1,1"
                    CornerRadius="7"
                    Padding="12,8"
                    Margin="4,0">
                <TextBlock x:Name="TxtCountSuperati"
                           HorizontalAlignment="Center"
                           VerticalAlignment="Center"
                           FontWeight="Bold"
                           FontSize="13"
                           Foreground="{DynamicResource PassFg}"
                           Text="[OK] 0 Superati"/>
            </Border>

            <!-- Falliti -->
            <Border Background="{DynamicResource FailBg}"
                    BorderBrush="{DynamicResource FailBorder}"
                    BorderThickness="4,1,1,1"
                    CornerRadius="7"
                    Padding="12,8"
                    Margin="4,0">
                <TextBlock x:Name="TxtCountFalliti"
                           HorizontalAlignment="Center"
                           VerticalAlignment="Center"
                           FontWeight="Bold"
                           FontSize="13"
                           Foreground="{DynamicResource FailFg}"
                           Text="[X] 0 Falliti"/>
            </Border>

            <!-- Sconosciuti -->
            <Border Background="{DynamicResource UnknownBg}"
                    BorderBrush="{DynamicResource UnknownBorder}"
                    BorderThickness="4,1,1,1"
                    CornerRadius="7"
                    Padding="12,8"
                    Margin="4,0">
                <TextBlock x:Name="TxtCountSconosciuti"
                           HorizontalAlignment="Center"
                           VerticalAlignment="Center"
                           FontWeight="Bold"
                           FontSize="13"
                           Foreground="{DynamicResource UnknownFg}"
                           Text="[?] 0 Sconosciuti"/>
            </Border>

            <!-- Non applicabili -->
            <Border Background="{DynamicResource NaBg}"
                    BorderBrush="{DynamicResource NaBorder}"
                    BorderThickness="4,1,1,1"
                    CornerRadius="7"
                    Padding="12,8"
                    Margin="4,0">
                <TextBlock x:Name="TxtCountNonApplicabili"
                           HorizontalAlignment="Center"
                           VerticalAlignment="Center"
                           FontWeight="Bold"
                           FontSize="13"
                           Foreground="{DynamicResource NaFg}"
                           Text="[-] 0 Non applicabili"/>
            </Border>

            <!-- Errori -->
            <Border Background="{DynamicResource ErrorBg}"
                    BorderBrush="{DynamicResource ErrorBorder}"
                    BorderThickness="4,1,1,1"
                    CornerRadius="7"
                    Padding="12,8"
                    Margin="4,0">
                <TextBlock x:Name="TxtCountErrori"
                           HorizontalAlignment="Center"
                           VerticalAlignment="Center"
                           FontWeight="Bold"
                           FontSize="13"
                           Foreground="{DynamicResource ErrorFg}"
                           Text="[!] 0 Errori"/>
            </Border>
        </UniformGrid>

        <!-- ================= RIGA 4: CORPO PRINCIPALE A 2 PAGINE ================= -->
        <Grid Grid.Row="4" Margin="20,4,20,10">

            <!-- ==================== PAGINA 1: TABELLA CONTROLLI & DETTAGLI ==================== -->
            <Grid x:Name="GridPaginaScansione" Visibility="Visible">
                <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="*"/>
                </Grid.RowDefinitions>

                <!-- Barra Filtri -->
                <Border Grid.Row="0"
                        Background="{DynamicResource BgSurface}"
                        BorderBrush="{DynamicResource BorderSubtle}"
                        BorderThickness="1"
                        CornerRadius="8"
                        Padding="14,9"
                        Margin="0,0,0,10">
                    <Grid>
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="155"/>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="145"/>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="185"/>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>

                        <TextBlock x:Name="LblFiltroStato" Grid.Column="0" Text="Stato:" VerticalAlignment="Center" FontWeight="SemiBold" Margin="0,0,8,0" Foreground="{DynamicResource TextSecondary}"/>
                        <ComboBox x:Name="CmbFiltroStato" Grid.Column="1" VerticalContentAlignment="Center" Margin="0,0,14,0" SelectedIndex="0">
                            <ComboBoxItem Content="Tutti"/>
                        </ComboBox>

                        <TextBlock x:Name="LblFiltroGravita" Grid.Column="2" Text="Gravita':" VerticalAlignment="Center" FontWeight="SemiBold" Margin="0,0,8,0" Foreground="{DynamicResource TextSecondary}"/>
                        <ComboBox x:Name="CmbFiltroGravita" Grid.Column="3" VerticalContentAlignment="Center" Margin="0,0,14,0" SelectedIndex="0">
                            <ComboBoxItem Content="Tutte"/>
                        </ComboBox>

                        <TextBlock x:Name="LblFiltroCategoria" Grid.Column="4" Text="Categoria:" VerticalAlignment="Center" FontWeight="SemiBold" Margin="0,0,8,0" Foreground="{DynamicResource TextSecondary}"/>
                        <ComboBox x:Name="CmbFiltroCategoria" Grid.Column="5" VerticalContentAlignment="Center" Margin="0,0,14,0" SelectedIndex="0">
                            <ComboBoxItem Content="Tutte"/>
                        </ComboBox>

                        <TextBlock x:Name="LblFiltroCerca" Grid.Column="6" Text="Cerca:" VerticalAlignment="Center" FontWeight="SemiBold" Margin="0,0,8,0" Foreground="{DynamicResource TextSecondary}"/>
                        <TextBox x:Name="TxtRicerca"
                                 Grid.Column="7"
                                 VerticalContentAlignment="Center"
                                 Padding="10,5"
                                 Margin="0,0,12,0"/>

                        <Button x:Name="BtnResetFiltri"
                                Style="{StaticResource ModernButton}"
                                Grid.Column="8"
                                Content="Reimposta filtri"
                                Padding="12,5"/>
                    </Grid>
                </Border>

                <!-- Tabella + Pannello Dettaglio -->
                <Grid Grid.Row="1">
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="3.1*" MinWidth="380"/>
                        <ColumnDefinition Width="12"/>
                        <ColumnDefinition Width="2.3*" MinWidth="320"/>
                    </Grid.ColumnDefinitions>

                    <!-- SINISTRA: Tabella Risultati -->
                    <Border Grid.Column="0"
                            Background="{DynamicResource BgSurface}"
                            BorderBrush="{DynamicResource BorderSubtle}"
                            BorderThickness="1"
                            CornerRadius="8"
                            ClipToBounds="True">
                        <Grid>
                            <DataGrid x:Name="GridRisultati"
                                      AutoGenerateColumns="False"
                                      IsReadOnly="True"
                                      SelectionMode="Single"
                                      SelectionUnit="FullRow"
                                      HeadersVisibility="Column"
                                      GridLinesVisibility="Horizontal"
                                      AlternationCount="2"
                                      HorizontalGridLinesBrush="{DynamicResource BorderSubtle}"
                                      Background="{DynamicResource BgSurface}"
                                      RowBackground="{DynamicResource BgSurface}"
                                      AlternatingRowBackground="{DynamicResource BgAlternating}"
                                      Foreground="{DynamicResource TextPrimary}"
                                      BorderThickness="0"
                                      RowHeight="36"
                                      HorizontalScrollBarVisibility="Auto"
                                      VerticalScrollBarVisibility="Auto"
                                      CanUserResizeColumns="True"
                                      CanUserAddRows="False"
                                      CanUserDeleteRows="False"
                                      CanUserReorderColumns="False">
                                <DataGrid.Columns>
                                    <DataGridTextColumn x:Name="ColStato" Header="Stato" Binding="{Binding StatusLabel}" Width="Auto" MinWidth="130"/>
                                    <DataGridTextColumn x:Name="ColGravita" Header="Gravita'" Binding="{Binding SeverityLabel}" Width="Auto" MinWidth="95"/>
                                    <DataGridTextColumn x:Name="ColCategoria" Header="Categoria" Binding="{Binding Category}" Width="Auto" MinWidth="150"/>
                                    <DataGridTextColumn x:Name="ColId" Header="ID" Binding="{Binding ControlId}" Width="Auto" MinWidth="130"/>
                                    <DataGridTextColumn x:Name="ColControllo" Header="Controllo" Binding="{Binding Title}" Width="Auto" MinWidth="560"/>
                                </DataGrid.Columns>
                            </DataGrid>

                            <!-- Overlay iniziale / lista vuota -->
                            <Border x:Name="PanelGuidaVuota"
                                    Background="{DynamicResource BgSurface}"
                                    CornerRadius="8"
                                    Padding="32"
                                    HorizontalAlignment="Stretch"
                                    VerticalAlignment="Stretch">
                                <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center" MaxWidth="440">
                                    <Border Background="{DynamicResource BgElevated}"
                                            BorderBrush="{DynamicResource BorderStrong}"
                                            BorderThickness="1"
                                            Width="64" Height="64"
                                            CornerRadius="32"
                                            HorizontalAlignment="Center"
                                            Margin="0,0,0,16">
                                        <Canvas Width="32" Height="32" HorizontalAlignment="Center" VerticalAlignment="Center">
                                            <Ellipse Canvas.Left="3" Canvas.Top="3" Width="18" Height="18" Stroke="#3B82F6" StrokeThickness="2.5"/>
