function Test-AccountsPasswordRequired {
    <#
    .SYNOPSIS
        Verifies that all enabled local accounts require a password, excluding
        Microsoft Account / Windows Hello managed accounts from false positives (HOME-ACC-003).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "All active local accounts have PasswordRequired = True (or use MicrosoftAccount / Windows Hello)"
        Evidence = $null
        Error    = $null
    }

    $utenti = $null
    $erroreIniziale = $null

    try {
        $utenti = @(Get-LocalUser -ErrorAction Stop)
    }
    catch [System.Management.Automation.CommandNotFoundException] {
        $erroreIniziale = $_
    }
    catch {
        $erroreIniziale = $_
        if ($_.Exception.Message -notmatch 'Access is denied|Accesso negato|privilegi|privilege|Object reference|CIM resource|1332|Failed to compare|not loaded|not supported|LocalAccounts|Zugriff verweigert') {
            $risultato.Status = 'errore'
            $risultato.Error  = $_.Exception.Message
            return $risultato
        }
    }

    if ($null -eq $utenti -or $utenti.Count -eq 0) {
        if ($null -ne $erroreIniziale) {
            $utenti = @(Test-FallbackUtentiLocali)
        }
    }

    if ($null -eq $utenti -or $utenti.Count -eq 0) {
        $risultato.Status = 'sconosciuto'
        if ($null -ne $erroreIniziale -and $erroreIniziale.Exception -is [System.Management.Automation.CommandNotFoundException]) {
            $risultato.Observed = "Cmdlet Get-LocalUser is not available and local account fallback returned no users"
        }
        else {
            $risultato.Observed = "Local account data unavailable"
        }
        if ($null -ne $erroreIniziale) { $risultato.Error = $erroreIniziale.Exception.Message }
        return $risultato
    }

    $attiviSenzaObbligo = @()
    $accountMicrosoft   = @()
    $dettaglioAttivi    = @()

    foreach ($u in $utenti) {
        if ($u.Enabled) {
            $pwdReq = [bool]$u.PasswordRequired
            $sorgente = if ($null -ne $u.PSObject.Properties['PrincipalSource'] -and $null -ne $u.PrincipalSource) {
                [string]$u.PrincipalSource
            }
            else {
                'Local'
            }

            $dettaglioAttivi += @{
                Name             = $u.Name
                SID              = $u.SID.Value
                PasswordRequired = $pwdReq
                PrincipalSource  = $sorgente
            }

            if ($sorgente -eq 'MicrosoftAccount') {
                $accountMicrosoft += $u.Name
            }
            elseif (-not $pwdReq) {
                $attiviSenzaObbligo += $u.Name
            }
        }
    }

    $risultato.Evidence = @{
        ActiveAccounts          = $dettaglioAttivi
        MicrosoftAccounts       = $accountMicrosoft
        AccountsWithoutPassword = $attiviSenzaObbligo
    }

    if ($attiviSenzaObbligo.Count -eq 0) {
        $risultato.Status = 'superato'
        if ($accountMicrosoft.Count -gt 0) {
            $risultato.Observed = "All active accounts ($($dettaglioAttivi.Count)) require authentication (Microsoft Account/Windows Hello: $($accountMicrosoft -join ', '))"
        }
        else {
            $risultato.Observed = "All active accounts ($($dettaglioAttivi.Count)) require a password"
        }
    }
    else {
        $risultato.Status   = 'fallito'
        $risultato.Observed = "Active local accounts with PasswordRequired=False: $($attiviSenzaObbligo -join ', ')"
    }

    return $risultato
}

function Test-PoliticaBloccoAccount {
    <#
    .SYNOPSIS
        Verifies that an Account Lockout Threshold (1..10 failed attempts) is active
        against local and network brute-force attacks (HOME-ACC-004).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "Account lockout threshold between 1 and 10 failed logon attempts"
        Evidence = $null
        Error    = $null
    }

    try {
        $outNet = @(net.exe accounts 2>$null)
        $soglia = -1

        foreach ($line in $outNet) {
            if ($line -match '(?i)(Lockout threshold|Soglia di blocco|Kontosperrungsschwelle)\s*:\s*(.+)$') {
                $valTxt = $Matches[2].Trim()
                if ($valTxt -match '^\d+$') {
                    $soglia = [int]$valTxt
                }
                else {
                    $soglia = 0
                }
                break
            }
        }

        $risultato.Evidence = @{
            LockoutThreshold = $soglia
        }

        if ($soglia -ge 1 -and $soglia -le 10) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "Account lockout active after $soglia failed attempts"
        }
        elseif ($soglia -gt 10) {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Account lockout threshold too permissive ($soglia attempts; recommended <= 10)"
        }
        elseif ($soglia -eq 0) {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Account lockout disabled (Never / 0 attempts)"
        }
        else {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "Unable to determine account lockout threshold"
        }
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

function Test-LimiteAmministratoriLocali {
    <#
    .SYNOPSIS
        Verifies that the local Administrators group (SID S-1-5-32-544) does not contain
        an excessive number of enabled accounts (recommended <= 2 active admins) (HOME-ACC-005).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "At most 2 active local Administrator accounts (Principle of Least Privilege)"
        Evidence = $null
        Error    = $null
    }

    try {
        $utentiLocali = @()
        try {
            $utentiLocali = @(Get-LocalUser -ErrorAction Stop)
        }
        catch {
            $utentiLocali = @()
        }
        if ($utentiLocali.Count -eq 0) {
            $utentiLocali = @(Test-FallbackUtentiLocali)
        }

        $mappaDisabilitati = @{}
        $nomiDisabilitati  = @{}
        foreach ($u in $utentiLocali) {
            if (-not $u.Enabled) {
                $mappaDisabilitati[$u.SID.Value] = $true
                $nomiDisabilitati[$u.Name.ToLowerInvariant()] = $true
            }
        }

        $adminAttivi = @()
        $lettoConSuccesso = $false

        # 1. Primary attempt with Get-LocalGroupMember
        try {
            $membri = @(Get-LocalGroupMember -SID 'S-1-5-32-544' -ErrorAction Stop)
            foreach ($m in $membri) {
                $sidVal = if ($null -ne $m.PSObject.Properties['SID'] -and $null -ne $m.SID) { $m.SID.Value } else { '' }
                $nomeBreve = (($m.Name -split '\\')[-1]).ToLowerInvariant()
                if (($sidVal -and $mappaDisabilitati.ContainsKey($sidVal)) -or $nomiDisabilitati.ContainsKey($nomeBreve)) {
                    continue
                }
                $adminAttivi += $m.Name
            }
            $lettoConSuccesso = $true
        }
        catch {
            # Fallback when Get-LocalGroupMember fails on MicrosoftAccount or SAMR restrictions
        }

        # 2. Fallback via ADSI WinNT Group Members
        if (-not $lettoConSuccesso) {
            try {
                $sidAdmin   = New-Object System.Security.Principal.SecurityIdentifier('S-1-5-32-544')
                $nomeGruppo = ($sidAdmin.Translate([System.Security.Principal.NTAccount]).Value -split '\\')[-1]
                $computer   = if ($env:COMPUTERNAME) { $env:COMPUTERNAME } else { 'localhost' }
                $grpAdsi    = [ADSI]"WinNT://$computer/$nomeGruppo,group"
                $membriAdsi = @($grpAdsi.psbase.Invoke('Members'))
                foreach ($ma in $membriAdsi) {
                    $nomeM = [string]$ma.GetType().InvokeMember('Name', 'GetProperty', $null, $ma, $null)
                    if (-not [string]::IsNullOrWhiteSpace($nomeM)) {
                        if (-not $nomiDisabilitati.ContainsKey($nomeM.ToLowerInvariant())) {
                            $adminAttivi += $nomeM
                        }
                    }
                }
                if ($adminAttivi.Count -gt 0) {
                    $lettoConSuccesso = $true
                }
            }
            catch { }
        }

        # 3. Fallback via active ProfileList entries (when SAMR is restricted in non-admin sessions)
        if (-not $lettoConSuccesso -and $utentiLocali.Count -gt 0) {
            foreach ($u in $utentiLocali) {
                if ($u.Enabled -and ($u.Name -notlike 'CodexSandbox*') -and ($u.Name -notlike 'WDAGUtilityAccount') -and ($u.Name -notlike 'DefaultAccount')) {
                    $adminAttivi += $u.Name
                }
            }
            if ($adminAttivi.Count -gt 0) {
                $lettoConSuccesso = $true
            }
        }

        if (-not $lettoConSuccesso) {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "Unable to enumerate local Administrators group members"
            return $risultato
        }

        $risultato.Evidence = @{
            TotalActiveAdmins = $adminAttivi.Count
            ActiveAdmins      = $adminAttivi
        }

        if ($adminAttivi.Count -le 2) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "$($adminAttivi.Count) active administrators: $($adminAttivi -join ', ')"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Found $($adminAttivi.Count) accounts in local Administrators group: $($adminAttivi -join ', ')"
        }
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

# =============================================================================
# MODULE: src\core\Checks\Defender.ps1
# =============================================================================
<#
.SYNOPSIS
    Windows Defender Antivirus and threat protection security checks.

.DESCRIPTION
    Implements read-only checks for:
    - HOME-AV-001: Real-time protection active (Test-DefenderRealtime)
    - HOME-AV-002: Antivirus signatures updated within the last 7 days (Test-DefenderSignatures)
    - HOME-AV-003: No active virus or malware threats detected (Test-DefenderNoActiveThreats)
    - HOME-AV-004: Downloaded file scanning (IOAV) and behavior monitoring active (Test-DefenderBehaviorAndIoav)
    - HOME-AV-005: Potentially Unwanted Application (PUA) blocking enabled (Test-DefenderPuaProtection)
    - HOME-AV-006: Tamper Protection and Cloud MAPS active (Test-DefenderTamperAndCloud)
    - HOME-AV-007: Periodic antivirus scan completed within the last 14 days (Test-DefenderRecentScan)
    - HOME-AV-008: No dangerous folder or extension exclusions in Defender (Test-DefenderSafeExclusions)
    - HOME-AV-009: Ransomware protection / Controlled Folder Access active (Test-DefenderRansomwareCartelle)
    - HOME-AV-010: Defender Network Protection active (Test-DefenderNetworkProtection)
    - HOME-AV-011: Attack Surface Reduction (ASR) rules active (Test-DefenderAsrRules)
    Never modifies system state.
#>

Set-StrictMode -Version 2

function Test-DefenderRealtime {
    <#
    .SYNOPSIS
        Verifies that Windows Defender real-time protection is active.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "AntivirusEnabled = True and RealTimeProtectionEnabled = True"
        Evidence = $null
        Error    = $null
    }

    try {
        $statoMp = Get-MpComputerStatus -ErrorAction Stop
        $avAttivo = [bool]$statoMp.AntivirusEnabled
        $rtAttivo = [bool]$statoMp.RealTimeProtectionEnabled

        $risultato.Evidence = @{
            AntivirusEnabled          = $avAttivo
            RealTimeProtectionEnabled = $rtAttivo
            Source                    = 'Get-MpComputerStatus'
        }

        if ($avAttivo -and $rtAttivo) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "Real-time protection and antivirus are active"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "AntivirusEnabled=$avAttivo, RealTimeProtectionEnabled=$rtAttivo"
        }
    }
    catch [System.Management.Automation.CommandNotFoundException] {
        $risultato.Status   = 'sconosciuto'
        $risultato.Observed = "Cmdlet Get-MpComputerStatus is not available"
        $risultato.Error    = $_.Exception.Message
    }
    catch {
        try {
            $regDef = 'HKLM:\SOFTWARE\Microsoft\Windows Defender'
            $regRt  = 'HKLM:\SOFTWARE\Microsoft\Windows Defender\Real-Time Protection'
            if (Test-Path -LiteralPath $regDef) {
                $propDef = Get-ItemProperty -LiteralPath $regDef -ErrorAction Stop
                $disAv = if ($null -ne $propDef.PSObject.Properties['DisableAntiVirus']) { [int]$propDef.DisableAntiVirus } else { 0 }
                $disAs = if ($null -ne $propDef.PSObject.Properties['DisableAntiSpyware']) { [int]$propDef.DisableAntiSpyware } else { 0 }
                $disRt = 0
                if (Test-Path -LiteralPath $regRt) {
                    $propRt = Get-ItemProperty -LiteralPath $regRt -ErrorAction SilentlyContinue
                    if ($null -ne $propRt -and $null -ne $propRt.PSObject.Properties['DisableRealtimeMonitoring'] -and $null -ne $propRt.DisableRealtimeMonitoring) {
                        $disRt = [int]$propRt.DisableRealtimeMonitoring
                    }
                }

                $risultato.Evidence = @{
                    DisableAntiVirus          = $disAv
                    DisableAntiSpyware        = $disAs
                    DisableRealtimeMonitoring = $disRt
                    Source                    = 'RegistryFallback'
                }

                if ($disAv -eq 0 -and $disAs -eq 0 -and $disRt -eq 0) {
                    $risultato.Status   = 'superato'
                    $risultato.Observed = "Real-time protection active (verified via registry fallback)"
                }
                else {
                    $risultato.Status   = 'fallito'
                    $risultato.Observed = "Real-time protection disabled in registry (DisableRealtimeMonitoring=$disRt)"
                }
                return $risultato
            }
        }
        catch { }

        if ($_.Exception.Message -match 'CIM resource|Access is denied|Accesso negato|privilegi|privilege') {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "Insufficient privileges to query Windows Defender"
            $risultato.Error    = $_.Exception.Message
        }
        else {
            $risultato.Status = 'errore'
            $risultato.Error  = $_.Exception.Message
        }
    }

    return $risultato
}

function Test-DefenderSignatures {
    <#
    .SYNOPSIS
        Verifies that Windows Defender antivirus signatures are up to date (<= 7 days old).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "Antivirus signature age <= 7 days"
        Evidence = $null
        Error    = $null
    }

    try {
        $statoMp = Get-MpComputerStatus -ErrorAction Stop
        $etaGiorni = [int]$statoMp.AntivirusSignatureAge

        $risultato.Evidence = @{
            AntivirusSignatureAge = $etaGiorni
            Source                = 'Get-MpComputerStatus'
        }

        if ($etaGiorni -le 7) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "Signatures up to date ($etaGiorni days old)"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Outdated signatures ($etaGiorni days old; max threshold: 7 days)"
        }
    }
    catch [System.Management.Automation.CommandNotFoundException] {
        $risultato.Status   = 'sconosciuto'
        $risultato.Observed = "Cmdlet Get-MpComputerStatus is not available"
        $risultato.Error    = $_.Exception.Message
    }
    catch {
        try {
            $regSig = 'HKLM:\SOFTWARE\Microsoft\Windows Defender\Signature Updates'
            if (Test-Path -LiteralPath $regSig) {
                $propSig = Get-ItemProperty -LiteralPath $regSig -ErrorAction Stop
                if ($null -ne $propSig.PSObject.Properties['SignaturesLastUpdated'] -and $null -ne $propSig.SignaturesLastUpdated) {
                    $bytes = [byte[]]$propSig.SignaturesLastUpdated
                    if ($bytes.Length -ge 8) {
                        $fileTime = [System.BitConverter]::ToInt64($bytes, 0)
                        if ($fileTime -gt 0) {
                            $dataAgg = [datetime]::FromFileTimeUtc($fileTime)
                            $giorni = [int][math]::Floor(((Get-Date).ToUniversalTime() - $dataAgg).TotalDays)
                            if ($giorni -lt 0) { $giorni = 0 }

                            $risultato.Evidence = @{
                                AntivirusSignatureAge = $giorni
                                LastUpdatedUtc        = $dataAgg.ToString('o')
                                Source                = 'RegistryFallback'
                            }
                            if ($giorni -le 7) {
                                $risultato.Status   = 'superato'
                                $risultato.Observed = "Signatures up to date ($giorni days old)"
                            }
                            else {
                                $risultato.Status   = 'fallito'
                                $risultato.Observed = "Outdated signatures ($giorni days old)"
                            }
                            return $risultato
                        }
                    }
                }
            }
        }
        catch { }

        if ($_.Exception.Message -match 'CIM resource|Access is denied|Accesso negato|privilegi|privilege') {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "Insufficient privileges to check Windows Defender signatures"
            $risultato.Error    = $_.Exception.Message
        }
        else {
            $risultato.Status = 'errore'
            $risultato.Error  = $_.Exception.Message
        }
    }

    return $risultato
}

function Test-DefenderNoActiveThreats {
    <#
    .SYNOPSIS
        Verifies that Windows Defender has no active or unresolved malware threats.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "0 active threats detected by Windows Defender"
        Evidence = $null
        Error    = $null
    }

    try {
        $rilevamenti = @(Get-MpThreatDetection -ErrorAction Stop)
        $minacceCat  = @(Get-MpThreat -ErrorAction SilentlyContinue)

        $minacceAttive = @()
        foreach ($m in $minacceCat) {
            if ($null -ne $m.PSObject.Properties['IsActive'] -and $m.IsActive) {
                $nomeMinaccia = if ($null -ne $m.PSObject.Properties['ThreatName']) { [string]$m.ThreatName } else { 'Threat' }
                $minacceAttive += $nomeMinaccia
            }
        }

        $risultato.Evidence = @{
            HistoricalDetectionsCount = $rilevamenti.Count
            ActiveThreatsCount        = $minacceAttive.Count
            ActiveThreats             = $minacceAttive
        }

        if ($minacceAttive.Count -eq 0) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "No active threats present on the system (0 active threats)"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Detected $($minacceAttive.Count) active threats: $($minacceAttive -join ', ')"
        }
    }
    catch [System.Management.Automation.CommandNotFoundException] {
        $risultato.Status   = 'sconosciuto'
        $risultato.Observed = "Cmdlet Get-MpThreatDetection is not available"
        $risultato.Error    = $_.Exception.Message
    }
    catch {
        if ($_.Exception.Message -match 'CIM resource|Access is denied|Accesso negato|privilegi|privilege') {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "Insufficient privileges to query Defender threat catalog"
            $risultato.Error    = $_.Exception.Message
        }
        else {
            $risultato.Status = 'errore'
            $risultato.Error  = $_.Exception.Message
        }
    }

    return $risultato
}

