function Test-DefenderAsrRules {
    <#
    .SYNOPSIS
        Verifies that Microsoft Defender Attack Surface Reduction (ASR) rules are active
        in Block (1) or Warn (6) mode, including LSASS credential theft and obfuscated script rules (HOME-AV-011).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "ASR rules active in Block (1) or Warn (6) mode (including LSASS 9e6c4e1f-... and Obfuscated Scripts 5beb7efe-...)"
        Evidence = $null
        Error    = $null
    }

    try {
        $pref = Get-MpPreference -ErrorAction Stop
        $ids = @()
        if ($null -ne $pref.PSObject.Properties['AttackSurfaceReductionRules_Ids'] -and $null -ne $pref.AttackSurfaceReductionRules_Ids) {
            $ids = @($pref.AttackSurfaceReductionRules_Ids)
        }
        $actions = @()
        if ($null -ne $pref.PSObject.Properties['AttackSurfaceReductionRules_Actions'] -and $null -ne $pref.AttackSurfaceReductionRules_Actions) {
            $actions = @($pref.AttackSurfaceReductionRules_Actions)
        }

        if ($ids.Count -gt 0 -and ([string]$ids[0]) -match 'Must be an administrator|amministratore') {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "Administrator privileges required to read Defender ASR rules"
            $risultato.Evidence = @{ RequiresAdmin = $true }
            return $risultato
        }

        $regoleAttive = @()
        $lsassAttiva  = $false
        $scriptAttiva = $false

        $maxIdx = [Math]::Min($ids.Count, $actions.Count)
        for ($i = 0; $i -lt $maxIdx; $i++) {
            $guid = ([string]$ids[$i]).Trim().ToLowerInvariant()
            $act  = [int]$actions[$i]
            if ($act -eq 1 -or $act -eq 6) {
                $regoleAttive += "$guid=$act"
                if ($guid -eq '9e6c4e1f-7d60-472f-ba1a-a39ef669e4b2') { $lsassAttiva  = $true }
                if ($guid -eq '5beb7efe-fd9a-4556-801d-275e5ffc04cc') { $scriptAttiva = $true }
            }
        }

        $risultato.Evidence = @{
            TotalConfigured  = $ids.Count
            TotalActive      = $regoleAttive.Count
            LsassProtected   = $lsassAttiva
            ScriptsProtected = $scriptAttiva
            ActiveRules      = $regoleAttive
        }

        if ($regoleAttive.Count -gt 0) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "$($regoleAttive.Count) ASR rules active in Block/Warn mode (LSASS=$lsassAttiva, ObfuscatedScripts=$scriptAttiva)"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "No Attack Surface Reduction (ASR) rules active in Block/Warn mode ($($ids.Count) configured)"
        }
    }
    catch [System.Management.Automation.CommandNotFoundException] {
        $risultato.Status   = 'sconosciuto'
        $risultato.Observed = "Cmdlet Get-MpPreference is not available"
        $risultato.Error    = $_.Exception.Message
    }
    catch {
        if ($_.Exception.Message -match 'CIM resource|Access is denied|Accesso negato|privilegi|privilege') {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "Insufficient privileges to check Defender ASR rules"
            $risultato.Error    = $_.Exception.Message
        }
        else {
            $risultato.Status = 'errore'
            $risultato.Error  = $_.Exception.Message
        }
    }

    return $risultato
}

# =============================================================================
# MODULE: src\core\Checks\FileSecurity.ps1
# =============================================================================
<#
.SYNOPSIS
    Local file security, startup persistence, Scheduled Tasks, IFEO, hosts file, WMI, and browser policy checks.

.DESCRIPTION
    Implements read-only checks for:
    - HOME-FIL-001: Disguised double-extension executables in Downloads, Desktop, and Temp (Test-SuspiciousDoubleExtensionFiles)
    - HOME-FIL-002: Suspicious or obfuscated Startup Run/RunOnce registry entries (Test-StartupPersistenceEntries)
    - HOME-FIL-003: Windows hosts file integrity against DNS hijacking (Test-HostsFileIntegrity)
    - HOME-FIL-004: Suspicious or obfuscated Scheduled Tasks (Test-TaskPianificatiSospetti)
    - HOME-FIL-005: IFEO Debugger hijacking on critical executables (Test-HijackingIFEO)
    - HOME-FIL-006: Suspicious scripts or executables in Startup folders (Test-CartellaStartupUtente)
    - HOME-FIL-007: Fileless persistence via WMI Event Subscriptions (Test-WmiEventSubscriptions)
    - HOME-FIL-008: Policy-forced Chrome/Edge browser extensions (Test-BrowserForcedExtensions)
    - HOME-FIL-009: No vulnerable unquoted service executable paths (Test-UnquotedServicePaths)
    Never modifies system state.
#>

Set-StrictMode -Version 2

function Test-SuspiciousDoubleExtensionFiles {
    <#
    .SYNOPSIS
        Performs a read-only scan of Downloads, Desktop, and Temp directories for
        disguised double-extension executables (e.g., invoice.pdf.exe, photo.jpg.scr).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null,

        [Parameter(Mandatory = $false)]
        [string[]]$CartelleDaControllare = @()
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "0 disguised double-extension executables in Downloads, Desktop, and Temp"
        Evidence = $null
        Error    = $null
    }

    try {
        if ($null -eq $CartelleDaControllare -or $CartelleDaControllare.Count -eq 0) {
            $profiloUtente = [Environment]::GetFolderPath('UserProfile')
            $CartelleDaControllare = @(
                (Join-Path $profiloUtente 'Downloads'),
                (Join-Path $profiloUtente 'Desktop'),
                [System.IO.Path]::GetTempPath()
            )
        }

        $patternDoppiaEstensione = '(?i)\.(pdf|doc|docx|xls|xlsx|ppt|pptx|txt|rtf|jpg|jpeg|png|gif|bmp|mp3|mp4|avi|zip|rar|7z)\.(exe|scr|bat|cmd|vbs|vbe|js|jse|wsf|wsh|ps1|hta|com|pif)$'

        $fileSospetti     = @()
        $totaleAnalizzati = 0

        foreach ($cartella in $CartelleDaControllare) {
            if ([string]::IsNullOrWhiteSpace($cartella)) { continue }
            if (-not (Test-Path -LiteralPath $cartella -ErrorAction SilentlyContinue)) { continue }

            $elementi = @(Get-ChildItem -LiteralPath $cartella -File -ErrorAction SilentlyContinue | Select-Object -First 1000)
            foreach ($file in $elementi) {
                $totaleAnalizzati++
                if ($file.Name -match $patternDoppiaEstensione) {
                    $fileSospetti += $file.FullName
                }
            }
        }

        $risultato.Evidence = @{
            ScannedFolders  = $CartelleDaControllare
            ScannedFiles    = $totaleAnalizzati
            SuspiciousFiles = $fileSospetti
        }

        if ($fileSospetti.Count -eq 0) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "No suspicious double-extension files found ($totaleAnalizzati files scanned)"
        }
        else {
            $risultato.Status   = 'fallito'
            $nomiBrevi = @($fileSospetti | ForEach-Object { Split-Path -Leaf $_ })
            $risultato.Observed = "Found $($fileSospetti.Count) suspicious double-extension files: $($nomiBrevi -join ', ')"
        }
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

function Test-StartupPersistenceEntries {
    <#
    .SYNOPSIS
        Inspects Startup registry keys (Run / RunOnce) for suspicious commands
        (execution from Temp, obfuscated PowerShell -enc, mshta, wscript).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "No suspicious or obfuscated startup entries in Run/RunOnce keys"
        Evidence = $null
        Error    = $null
    }

    try {
        $chiaviRun = @(
            'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run',
            'HKCU:\Software\Microsoft\Windows\CurrentVersion\RunOnce',
            'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run',
            'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce'
        )

        $patternSospetto = '(?i)(-enc|-EncodedCommand|-w\s+hidden|-WindowStyle\s+Hidden|mshta\.exe|wscript\.exe|cscript\.exe|regsvr32\.exe\s+/s|\\AppData\\Local\\Temp\\|\\Windows\\Temp\\)'

        $vociTotali   = @()
        $vociSospette = @()

        foreach ($percorso in $chiaviRun) {
            if (-not (Test-Path -LiteralPath $percorso)) { continue }

            $prop = Get-ItemProperty -LiteralPath $percorso -ErrorAction SilentlyContinue
            if ($null -eq $prop) { continue }

            foreach ($p in $prop.PSObject.Properties) {
                if ($p.Name -in @('PSPath', 'PSParentPath', 'PSChildName', 'PSDrive', 'PSProvider')) {
                    continue
                }
                $valoreCmd = [string]$p.Value
                $voceDesc  = "$($p.Name) = $valoreCmd"
                $vociTotali += $voceDesc

                if ($valoreCmd -match $patternSospetto) {
                    $vociSospette += "$($p.Name) ($percorso)"
                }
            }
        }

        $risultato.Evidence = @{
            TotalRunEntries   = $vociTotali.Count
            SuspiciousEntries = $vociSospette
        }

        if ($vociSospette.Count -eq 0) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "No suspicious startup entries detected across $($vociTotali.Count) Run/RunOnce entries"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Detected $($vociSospette.Count) suspicious startup entries: $($vociSospette -join '; ')"
        }
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

function Test-HostsFileIntegrity {
    <#
    .SYNOPSIS
        Verifies that the Windows hosts file does not hijack security or Windows Update domains.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null,

        [Parameter(Mandatory = $false)]
        [string]$PercorsoHosts = ''
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "No hijacking of Microsoft or antivirus domains in the hosts file"
        Evidence = $null
        Error    = $null
    }

    try {
        if ([string]::IsNullOrWhiteSpace($PercorsoHosts)) {
            $sysRoot = if ($env:SystemRoot) { $env:SystemRoot } else { 'C:\Windows' }
            $PercorsoHosts = Join-Path $sysRoot 'System32\drivers\etc\hosts'
        }

        if (-not (Test-Path -LiteralPath $PercorsoHosts)) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "Hosts file not present (no active redirections)"
            return $risultato
        }

        $righe = @(Get-Content -LiteralPath $PercorsoHosts -Encoding UTF8 -ErrorAction Stop)
        $righeAttive   = @()
        $righeSospette = @()

        $patternDominiSensibili = '(?i)(windowsupdate\.com|update\.microsoft\.com|microsoft\.com|defender|virustotal\.com|malwarebytes\.com|kaspersky|bitdefender|avast|Norton|mcafee)'

        foreach ($riga in $righe) {
            $trimmed = $riga.Trim()
            if ($trimmed -eq '' -or $trimmed.StartsWith('#')) {
                continue
            }
            if ($trimmed -match '^(127\.0\.0\.1|::1)\s+localhost(\s|$)') {
                continue
            }
            $righeAttive += $trimmed
            if ($trimmed -match $patternDominiSensibili) {
                $righeSospette += $trimmed
            }
        }

        $risultato.Evidence = @{
            Path                = $PercorsoHosts
            CustomEntriesCount  = $righeAttive.Count
            SuspiciousRedirects = $righeSospette
        }

        if ($righeSospette.Count -eq 0) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "Hosts file intact ($($righeAttive.Count) custom entries, 0 security hijacks)"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Detected $($righeSospette.Count) suspicious hosts redirections: $($righeSospette -join '; ')"
        }
    }
    catch [System.UnauthorizedAccessException] {
        $risultato.Status   = 'sconosciuto'
        $risultato.Observed = "Access denied while reading the hosts file"
        $risultato.Error    = $_.Exception.Message
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

function Test-TaskPianificatiSospetti {
    <#
    .SYNOPSIS
        Audits non-Microsoft Scheduled Tasks for malware persistence indicators
        (execution from Temp/Users\Public, obfuscated PowerShell -enc, mshta, regsvr32, certutil) (HOME-FIL-004).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "0 suspicious or obfuscated Scheduled Tasks"
        Evidence = $null
        Error    = $null
    }

    try {
        $tasks = @(Get-ScheduledTask -ErrorAction Stop | Where-Object { $_.State -ne 'Disabled' -and $_.TaskPath -notlike '\Microsoft\*' })
        $patternCmdSospetto = '(?i)(-enc\b|-EncodedCommand|FromBase64String|DownloadString|mshta\.exe|certutil\.exe.*-urlcache|regsvr32\.exe.*scrobj|\\AppData\\Local\\Temp\\|\\Users\\Public\\)'

        $sospetti = @()
        foreach ($t in $tasks) {
            foreach ($act in $t.Actions) {
                $exe = if ($null -ne $act.PSObject.Properties['Execute']) { [string]$act.Execute } else { '' }
                $arg = if ($null -ne $act.PSObject.Properties['Arguments']) { [string]$act.Arguments } else { '' }
                $combinato = "$exe $arg".Trim()
                if ($combinato -match $patternCmdSospetto) {
                    $sospetti += "$($t.TaskName) ($combinato)"
                }
            }
        }

        $risultato.Evidence = @{
            AnalyzedTasks   = $tasks.Count
            SuspiciousTasks = $sospetti
        }

        if ($sospetti.Count -eq 0) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "No suspicious scheduled tasks detected ($($tasks.Count) non-Microsoft tasks inspected)"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Detected $($sospetti.Count) suspicious scheduled tasks: $($sospetti -join '; ')"
        }
    }
    catch [System.Management.Automation.CommandNotFoundException] {
        $risultato.Status   = 'sconosciuto'
        $risultato.Observed = "Cmdlet Get-ScheduledTask is not available"
        $risultato.Error    = $_.Exception.Message
    }
    catch {
        if ($_.Exception.Message -match 'CIM resource|Access is denied|Accesso negato|privilegi|privilege') {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "Administrator privileges required to inspect all Scheduled Tasks"
            $risultato.Error    = $_.Exception.Message
        }
        else {
            $risultato.Status = 'errore'
            $risultato.Error  = $_.Exception.Message
        }
    }

    return $risultato
}

function Test-HijackingIFEO {
    <#
    .SYNOPSIS
        Verifies that no critical system or accessibility executables (sethc.exe, utilman.exe,
        taskmgr.exe, MsMpEng.exe) have an IFEO Debugger hijack configured (HOME-FIL-005).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "No malicious IFEO Debugger values on critical system or accessibility executables"
        Evidence = $null
        Error    = $null
    }

    try {
        $baseIfeo = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options'
        $eseguibiliCritici = @(
            'sethc.exe', 'utilman.exe', 'osk.exe', 'narrator.exe', 'magnify.exe',
            'displayswitch.exe', 'atbroker.exe', 'taskmgr.exe', 'MsMpEng.exe',
            'MpCmdRun.exe', 'SecHealthUI.exe', 'regedit.exe', 'powershell.exe'
        )

        $dirottati = @()
        foreach ($exeName in $eseguibiliCritici) {
            $chiaveExe = Join-Path $baseIfeo $exeName
            if (Test-Path -LiteralPath $chiaveExe -ErrorAction SilentlyContinue) {
                $prop = Get-ItemProperty -LiteralPath $chiaveExe -Name 'Debugger' -ErrorAction SilentlyContinue
                if ($null -ne $prop -and $null -ne $prop.PSObject.Properties['Debugger'] -and (-not [string]::IsNullOrWhiteSpace([string]$prop.Debugger))) {
                    $dirottati += "$exeName -> $($prop.Debugger)"
                }
            }
        }

        $risultato.Evidence = @{
            CheckedExecutables = $eseguibiliCritici.Count
            IfeoHijacks        = $dirottati
        }

        if ($dirottati.Count -eq 0) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "No IFEO hijacking detected on critical system executables ($($eseguibiliCritici.Count) checked)"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Suspicious IFEO hijacks detected: $($dirottati -join '; ')"
        }
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

function Test-CartellaStartupUtente {
    <#
    .SYNOPSIS
        Scans user and common Startup folders for suspicious scripts or executables
        (.vbs, .js, .bat, .cmd, .ps1, .hta, .scr) (HOME-FIL-006).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "0 suspicious scripts or executables in Startup folders"
        Evidence = $null
        Error    = $null
    }

    try {
        $cartelleStartup = @(
            [Environment]::GetFolderPath('Startup'),
            [Environment]::GetFolderPath('CommonStartup')
        )

        $patternScriptSospetto = '(?i)\.(vbs|vbe|js|jse|wsf|wsh|hta|bat|cmd|ps1|scr|pif)$'
        $trovati = @()
        $totFile = 0

        foreach ($dir in $cartelleStartup) {
            if ([string]::IsNullOrWhiteSpace($dir) -or (-not (Test-Path -LiteralPath $dir -ErrorAction SilentlyContinue))) { continue }
            $files = @(Get-ChildItem -LiteralPath $dir -File -ErrorAction SilentlyContinue)
            foreach ($f in $files) {
                if ($f.Name -eq 'desktop.ini') { continue }
                $totFile++
                if ($f.Name -match $patternScriptSospetto) {
                    $trovati += $f.FullName
                }
            }
        }

        $risultato.Evidence = @{
            TotalStartupFiles = $totFile
            SuspiciousScripts = $trovati
        }

        if ($trovati.Count -eq 0) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "No suspicious scripts in Startup folders ($totFile items checked)"
        }
        else {
            $risultato.Status   = 'fallito'
            $nomi = @($trovati | ForEach-Object { Split-Path -Leaf $_ })
            $risultato.Observed = "Suspicious scripts/executables detected in Startup: $($nomi -join ', ')"
        }
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

function Test-WmiEventSubscriptions {
    <#
    .SYNOPSIS
        Verifies that no malicious permanent WMI event subscriptions exist
        (fileless persistence via __EventFilter, CommandLineEventConsumer,
        ActiveScriptEventConsumer, and __FilterToConsumerBinding in root\subscription) (HOME-FIL-007).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "0 suspicious permanent WMI subscriptions (CommandLineEventConsumer / ActiveScriptEventConsumer)"
        Evidence = $null
        Error    = $null
    }

    try {
        $filtri          = @(Get-CimInstance -Namespace 'root\subscription' -ClassName '__EventFilter' -ErrorAction Stop)
        $cmdConsumers    = @(Get-CimInstance -Namespace 'root\subscription' -ClassName 'CommandLineEventConsumer' -ErrorAction Stop)
        $scriptConsumers = @(Get-CimInstance -Namespace 'root\subscription' -ClassName 'ActiveScriptEventConsumer' -ErrorAction Stop)
        $bindings        = @(Get-CimInstance -Namespace 'root\subscription' -ClassName '__FilterToConsumerBinding' -ErrorAction Stop)

        $elementiSospetti = @()
        $filtriLegittimi = @('SCM Event Log Filter')

        foreach ($c in $cmdConsumers) {
            $nomeC  = if ($null -ne $c.PSObject.Properties['Name'] -and $null -ne $c.Name) { [string]$c.Name } else { 'UnnamedConsumer' }
            $cmdTpl = if ($null -ne $c.PSObject.Properties['CommandLineTemplate'] -and $null -ne $c.CommandLineTemplate) { [string]$c.CommandLineTemplate } else { '' }
            if ($cmdTpl.Length -gt 120) {
                $cmdTpl = $cmdTpl.Substring(0, 117) + '...'
            }
            $elementiSospetti += "CommandLineEventConsumer: $nomeC ($cmdTpl)"
        }

        foreach ($s in $scriptConsumers) {
            $nomeS  = if ($null -ne $s.PSObject.Properties['Name'] -and $null -ne $s.Name) { [string]$s.Name } else { 'UnnamedScriptConsumer' }
            $scrTxt = if ($null -ne $s.PSObject.Properties['ScriptText'] -and $null -ne $s.ScriptText) { [string]$s.ScriptText } else { '' }
            if ($scrTxt.Length -gt 120) {
                $scrTxt = $scrTxt.Substring(0, 117) + '...'
            }
            $elementiSospetti += "ActiveScriptEventConsumer: $nomeS ($scrTxt)"
        }

        foreach ($f in $filtri) {
            $fNome = if ($null -ne $f.PSObject.Properties['Name'] -and $null -ne $f.Name) { [string]$f.Name } else { '' }
            if ($filtriLegittimi -contains $fNome) { continue }
            $fQuery = if ($null -ne $f.PSObject.Properties['Query'] -and $null -ne $f.Query) { [string]$f.Query } else { '' }
            if ($fQuery.Length -gt 120) {
                $fQuery = $fQuery.Substring(0, 117) + '...'
            }
            if (($cmdConsumers.Count -gt 0 -or $scriptConsumers.Count -gt 0) -or
                ($fQuery -match '(?i)(powershell|cmd\.exe|wscript|cscript|mshta|Win32_ProcessStartTrace)')) {
                $elementiSospetti += "EventFilter: $fNome ($fQuery)"
            }
        }

        $bindingsNonStandard = 0
        foreach ($b in $bindings) {
            $bFilt = if ($null -ne $b.PSObject.Properties['Filter'] -and $null -ne $b.Filter) { [string]$b.Filter } else { '' }
            $bCons = if ($null -ne $b.PSObject.Properties['Consumer'] -and $null -ne $b.Consumer) { [string]$b.Consumer } else { '' }
            if (($bFilt -match 'SCM Event Log Filter') -and ($bCons -match 'NTEventLogEventConsumer')) {
                continue
            }
            $bindingsNonStandard++
        }

        $risultato.Evidence = @{
            EventFiltersCount          = $filtri.Count
            CommandLineConsumersCount  = $cmdConsumers.Count
            ActiveScriptConsumersCount = $scriptConsumers.Count
            BindingsCount              = $bindings.Count
            NonStandardBindingsCount   = $bindingsNonStandard
            SuspiciousItems            = $elementiSospetti
        }

        if ($elementiSospetti.Count -eq 0) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "No suspicious permanent WMI subscriptions detected in root\subscription"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Detected $($elementiSospetti.Count) suspicious WMI subscriptions: $($elementiSospetti -join '; ')"
        }
    }
    catch [System.UnauthorizedAccessException] {
        $risultato.Status   = 'sconosciuto'
        $risultato.Observed = "Insufficient privileges to query WMI namespace root\subscription"
        $risultato.Error    = $_.Exception.Message
    }
    catch {
        if ($_.Exception.Message -match 'Access is denied|Accesso negato|privilegi|privilege|CIM resource|Unauthorized') {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "Insufficient privileges to query WMI namespace root\subscription"
            $risultato.Error    = $_.Exception.Message
        }
        else {
            $risultato.Status = 'errore'
            $risultato.Error  = $_.Exception.Message
        }
    }

    return $risultato
}

function Test-BrowserForcedExtensions {
    <#
    .SYNOPSIS
        Verifies that no browser extensions are force-installed via registry policy
        (ExtensionInstallForcelist for Google Chrome or Microsoft Edge) (HOME-FIL-008).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "No policy-forced browser extensions (ExtensionInstallForcelist empty or absent)"
        Evidence = $null
        Error    = $null
    }

    try {
        $chiaviBrowser = @(
            @{ Browser = 'Chrome'; Hive = 'HKLM'; Path = 'HKLM:\SOFTWARE\Policies\Google\Chrome\ExtensionInstallForcelist' },
            @{ Browser = 'Chrome'; Hive = 'HKCU'; Path = 'HKCU:\SOFTWARE\Policies\Google\Chrome\ExtensionInstallForcelist' },
            @{ Browser = 'Edge';   Hive = 'HKLM'; Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Edge\ExtensionInstallForcelist' },
            @{ Browser = 'Edge';   Hive = 'HKCU'; Path = 'HKCU:\SOFTWARE\Policies\Microsoft\Edge\ExtensionInstallForcelist' }
        )

        $estensioniForzate = @()
        $chiaviTrovate     = @()

        foreach ($voce in $chiaviBrowser) {
            if (-not (Test-Path -LiteralPath $voce.Path -ErrorAction SilentlyContinue)) {
                continue
            }
            $chiaviTrovate += $voce.Path
            $prop = Get-ItemProperty -LiteralPath $voce.Path -ErrorAction Stop
            if ($null -eq $prop) { continue }

            foreach ($p in $prop.PSObject.Properties) {
                if ($p.Name -in @('PSPath', 'PSParentPath', 'PSChildName', 'PSDrive', 'PSProvider')) {
                    continue
                }
                $valEst = [string]$p.Value
                if (-not [string]::IsNullOrWhiteSpace($valEst)) {
                    $estensioniForzate += "$($voce.Browser) ($($voce.Hive)): $valEst"
                }
            }
        }

        $risultato.Evidence = @{
            CheckedKeys      = $chiaviBrowser.Count
            ExistingKeys     = $chiaviTrovate
            ForcedExtensions = $estensioniForzate
            TotalDetected    = $estensioniForzate.Count
        }

        if ($estensioniForzate.Count -eq 0) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "No policy-forced browser extensions detected for Chrome or Edge"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Detected $($estensioniForzate.Count) policy-forced browser extensions: $($estensioniForzate -join '; ')"
        }
    }
    catch [System.Security.SecurityException] {
        $risultato.Status   = 'sconosciuto'
        $risultato.Observed = "Access denied to browser policy registry keys"
        $risultato.Error    = $_.Exception.Message
    }
    catch [System.UnauthorizedAccessException] {
        $risultato.Status   = 'sconosciuto'
        $risultato.Observed = "Access denied to browser policy registry keys"
        $risultato.Error    = $_.Exception.Message
    }
    catch {
        if ($_.Exception.Message -match 'Access is denied|Accesso negato|privilegi|privilege|SecurityException') {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "Access denied to browser policy registry keys"
            $risultato.Error    = $_.Exception.Message
        }
        else {
            $risultato.Status = 'errore'
            $risultato.Error  = $_.Exception.Message
        }
    }

    return $risultato
}

function Test-UnquotedServicePaths {
    <#
    .SYNOPSIS
        Checks all Windows services for exploitable unquoted executable paths containing spaces (HOME-FIL-009).
    .DESCRIPTION
        Queries Win32_Service in read-only mode and inspects each service PathName. Flags third-party
        services whose unquoted .exe path contains whitespace and does not reside under SystemRoot.
    .PARAMETER Controllo
        Control object from the security catalog.
    .PARAMETER Ambiente
        Environment object returned by Get-AmbienteSistema.
    .OUTPUTS
        PSCustomObject with properties: Status, Observed, Expected, Evidence, Error.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $result = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "0 vulnerable unquoted third-party service executable paths"
        Evidence = $null
        Error    = $null
    }

    try {
        $services   = @(Get-CimInstance -ClassName Win32_Service -ErrorAction Stop)
        $systemRoot = if (-not [string]::IsNullOrWhiteSpace($env:SystemRoot)) { $env:SystemRoot.TrimEnd('\') } else { 'C:\Windows' }

        $vulnerableServices = @()
        foreach ($svc in $services) {
            $svcName = if ($null -ne $svc.PSObject.Properties['Name'] -and $null -ne $svc.Name) { [string]$svc.Name } else { 'UnknownService' }
            $pathName = if ($null -ne $svc.PSObject.Properties['PathName'] -and $null -ne $svc.PathName) { ([string]$svc.PathName).Trim() } else { '' }

            if ([string]::IsNullOrWhiteSpace($pathName) -or $pathName.StartsWith('"')) {
                continue
            }

            if ($pathName -match '^(?i)(.+?\.exe)(?:\s|$)') {
                $exePath = $Matches[1].Trim()
            }
            else {
                continue
            }

            if ($exePath -notmatch '\s') {
                continue
            }

            if ($exePath.StartsWith("$systemRoot\", [System.StringComparison]::OrdinalIgnoreCase) -or
                $exePath.StartsWith('\SystemRoot\', [System.StringComparison]::OrdinalIgnoreCase)) {
                continue
            }

            $vulnerableServices += "$svcName ($pathName)"
        }

        $result.Evidence = @{
            TotalServicesInspected = $services.Count
            VulnerableCount        = $vulnerableServices.Count
            VulnerableServices     = $vulnerableServices
        }

        if ($vulnerableServices.Count -eq 0) {
            $result.Status   = 'superato'
            $result.Observed = "No vulnerable unquoted service paths detected ($($services.Count) services inspected)"
        }
        else {
            $result.Status   = 'fallito'
            $result.Observed = "Detected $($vulnerableServices.Count) vulnerable unquoted service path(s): $($vulnerableServices -join '; ')"
        }
    }
    catch [System.UnauthorizedAccessException] {
        $result.Status   = 'sconosciuto'
        $result.Observed = "Insufficient privileges to query Windows services (Win32_Service)"
        $result.Error    = $_.Exception.Message
    }
    catch {
        if ($_.Exception.Message -match 'Access is denied|Accesso negato|privileg|CIM resource|Unauthorized') {
            $result.Status   = 'sconosciuto'
            $result.Observed = "Insufficient privileges to query Windows services (Win32_Service)"
            $result.Error    = $_.Exception.Message
        }
        else {
            $result.Status = 'errore'
            $result.Error  = $_.Exception.Message
        }
    }

    return $result
}

# =============================================================================
# MODULE: src\core\Checks\Network.ps1
# =============================================================================
<#
.SYNOPSIS
    Network protocol and exposure security controls.

.DESCRIPTION
    Implements read-only checks for:
    - HOME-NET-001: SMBv1 protocol disabled (Test-Smb1Disabled)
    - HOME-NET-002: NetBIOS over TCP/IP disabled (Test-NetbiosDisabled)
    - HOME-NET-003: LLMNR multicast name resolution disabled (Test-LlmnrDisabled)
    - HOME-NET-004: No non-standard SMB shares exposed (Test-CondivisioniSmbPericolose)
    - HOME-NET-005: Mandatory SMB signing enabled (Test-FirmaSmbObbligatoria)
    - HOME-NET-006: WinRM service disabled/stopped (Test-WinRmDisabilitatoOSicuro)
    - HOME-NET-007: WPAD auto-discovery disabled (Test-WpadDisabilitato)
    - HOME-NET-008: Legacy TLS 1.0/1.1 disabled and DoH supported (Test-LegacyTlsAndDoh)
    Never modifies system state.
#>

Set-StrictMode -Version 2

function Test-Smb1Disabled {
    <#
    .SYNOPSIS
        Verifies that the legacy SMBv1 protocol is disabled.
    .PARAMETER Controllo
        Control object from the catalog.
    .PARAMETER Ambiente
        Environment object (from Get-AmbienteSistema).
    .OUTPUTS
        PSCustomObject with properties: Status, Observed, Expected, Evidence, Error.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "SMBv1 protocol disabled (EnableSMB1Protocol = False)"
        Evidence = $null
        Error    = $null
    }

    try {
        $smbConfig = Get-SmbServerConfiguration -ErrorAction Stop
        $smb1Attivo = [bool]$smbConfig.EnableSMB1Protocol

        $risultato.Evidence = @{
            EnableSMB1Protocol = $smb1Attivo
            Source             = 'Get-SmbServerConfiguration'
        }

        if (-not $smb1Attivo) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "SMBv1 disabled"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "SMBv1 enabled (EnableSMB1Protocol = True)"
        }
    }
    catch {
        # Registry fallback (LanmanServer\Parameters and mrxsmb10 driver)
        try {
            $percorsoLanman = 'HKLM:\SYSTEM\CurrentControlSet\Services\LanmanServer\Parameters'
            $percorsoMrx    = 'HKLM:\SYSTEM\CurrentControlSet\Services\mrxsmb10'

            if (Test-Path -LiteralPath $percorsoLanman) {
                $propLanman = Get-ItemProperty -LiteralPath $percorsoLanman -ErrorAction Stop
                if ($null -ne $propLanman.PSObject.Properties['SMB1'] -and $null -ne $propLanman.SMB1) {
                    $valSmb1 = [int]$propLanman.SMB1
                    $risultato.Evidence = @{ SMB1Registry = $valSmb1; Source = 'LanmanServerRegistry' }
                    if ($valSmb1 -eq 0) {
                        $risultato.Status   = 'superato'
                        $risultato.Observed = "SMBv1 disabled via registry (SMB1 = 0)"
                    }
                    else {
                        $risultato.Status   = 'fallito'
                        $risultato.Observed = "SMBv1 enabled via registry (SMB1 = $valSmb1)"
                    }
                    return $risultato
                }
            }

            # If mrxsmb10 driver is absent or has Start = 4 (Disabled), SMBv1 is inactive
            if (-not (Test-Path -LiteralPath $percorsoMrx)) {
                $risultato.Evidence = @{ MrxSmb10Present = $false; Source = 'ServiceRegistry' }
                $risultato.Status   = 'superato'
                $risultato.Observed = "SMBv1 driver (mrxsmb10) is not installed on the system"
                return $risultato
            }
            else {
                $propMrx = Get-ItemProperty -LiteralPath $percorsoMrx -ErrorAction Stop
                $startVal = if ($null -ne $propMrx.PSObject.Properties['Start']) { [int]$propMrx.Start } else { 3 }
                $risultato.Evidence = @{ MrxSmb10Present = $true; Start = $startVal; Source = 'ServiceRegistry' }
                if ($startVal -eq 4) {
                    $risultato.Status   = 'superato'
                    $risultato.Observed = "SMBv1 driver disabled (Start = 4)"
                }
                else {
                    $risultato.Status   = 'fallito'
                    $risultato.Observed = "SMBv1 driver present and not disabled (Start = $startVal)"
                }
                return $risultato
            }
        }
        catch {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "Unable to determine SMBv1 status"
            $risultato.Error    = $_.Exception.Message
        }
    }

    return $risultato
}

function Test-NetbiosDisabled {
    <#
    .SYNOPSIS
        Verifies that NetBIOS over TCP/IP is disabled (NetbiosOptions = 2) on network interfaces.
    .PARAMETER Controllo
        Control object from the catalog.
    .PARAMETER Ambiente
        Environment object (from Get-AmbienteSistema).
    .OUTPUTS
        PSCustomObject with properties: Status, Observed, Expected, Evidence, Error.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "NetbiosOptions = 2 (Disabled) on all TCP/IP interfaces"
        Evidence = $null
        Error    = $null
    }

    try {
        $percorsoInterfacce = 'HKLM:\SYSTEM\CurrentControlSet\Services\NetBT\Parameters\Interfaces'
        if (-not (Test-Path -LiteralPath $percorsoInterfacce)) {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "NetBT Interfaces registry key not found"
            return $risultato
        }

        $sottoChiavi = @(Get-ChildItem -LiteralPath $percorsoInterfacce -ErrorAction Stop)
        if ($sottoChiavi.Count -eq 0) {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "No TCP/IP interfaces found under NetBT"
            return $risultato
        }

        $interfacceNonDisabilitate = @()
        $dettaglioInterfacce = @{}

        foreach ($chiave in $sottoChiavi) {
            $nomeIf = $chiave.PSChildName
            $propIf = Get-ItemProperty -LiteralPath $chiave.PSPath -ErrorAction Stop
            $opzione = if ($null -ne $propIf.PSObject.Properties['NetbiosOptions'] -and $null -ne $propIf.NetbiosOptions) {
                [int]$propIf.NetbiosOptions
            }
            else {
                0
            }

            $dettaglioInterfacce[$nomeIf] = $opzione
            if ($opzione -ne 2) {
                $interfacceNonDisabilitate += "$nomeIf (NetbiosOptions=$opzione)"
            }
        }

        $risultato.Evidence = $dettaglioInterfacce

        if ($interfacceNonDisabilitate.Count -eq 0) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "NetBIOS disabled (NetbiosOptions=2) on all $($sottoChiavi.Count) interfaces"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "NetBIOS enabled or default on $($interfacceNonDisabilitate.Count)/$($sottoChiavi.Count) interfaces"
        }
    }
    catch [System.Security.SecurityException] {
        $risultato.Status   = 'sconosciuto'
        $risultato.Observed = "Access denied to NetBT registry key"
        $risultato.Error    = $_.Exception.Message
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

function Test-LlmnrDisabled {
    <#
    .SYNOPSIS
        Verifies that LLMNR (Link-Local Multicast Name Resolution) is disabled (EnableMulticast = 0).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "EnableMulticast = 0 in HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient"
        Evidence = $null
        Error    = $null
    }

    try {
        $percorsoDns = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient'
        if (-not (Test-Path -LiteralPath $percorsoDns)) {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "DNSClient policy not configured (LLMNR active by default)"
            $risultato.Evidence = @{ Path = $percorsoDns; KeyExists = $false }
            return $risultato
        }

        $propDns = Get-ItemProperty -LiteralPath $percorsoDns -ErrorAction Stop
        $valore = if ($null -ne $propDns.PSObject.Properties['EnableMulticast'] -and $null -ne $propDns.EnableMulticast) {
            [int]$propDns.EnableMulticast
        }
        else {
            1
        }

        $risultato.Evidence = @{
            Path            = $percorsoDns
            EnableMulticast = $valore
        }

        if ($valore -eq 0) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "LLMNR disabled (EnableMulticast = 0)"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "LLMNR enabled (EnableMulticast = $valore)"
        }
    }
    catch [System.Security.SecurityException] {
        $risultato.Status   = 'sconosciuto'
        $risultato.Observed = "Access denied to DNSClient registry key"
        $risultato.Error    = $_.Exception.Message
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

function Test-CondivisioniSmbPericolose {
    <#
    .SYNOPSIS
        Verifies that no non-standard user SMB network shares are exposed
        (excluding default administrative shares ADMIN$, C$, IPC$, print$) (HOME-NET-004).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "0 unprotected or unnecessary user SMB shares"
        Evidence = $null
        Error    = $null
    }

    try {
        $shares = @(Get-SmbShare -ErrorAction Stop)
        $nonStandard = @()
        foreach ($s in $shares) {
            $nome = [string]$s.Name
            if ($nome -notmatch '^(ADMIN\$|IPC\$|print\$|[A-Za-z]\$)$') {
                $nonStandard += "$nome ($($s.Path))"
            }
        }

        $risultato.Evidence = @{
            TotalShares       = $shares.Count
            NonStandardShares = $nonStandard
        }

        if ($nonStandard.Count -eq 0) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "No non-standard shared folders exposed on the network"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Network shared folders detected ($($nonStandard.Count)): $($nonStandard -join '; ')"
        }
    }
    catch {
        # Registry fallback (HKLM:\SYSTEM\CurrentControlSet\Services\LanmanServer\Shares)
        try {
            $chiaveShares = 'HKLM:\SYSTEM\CurrentControlSet\Services\LanmanServer\Shares'
            if (Test-Path -LiteralPath $chiaveShares -ErrorAction SilentlyContinue) {
                $propShares = Get-ItemProperty -LiteralPath $chiaveShares -ErrorAction Stop
                $nonStdReg = @()
                foreach ($p in $propShares.PSObject.Properties) {
                    if ($p.Name -in @('PSPath', 'PSParentPath', 'PSChildName', 'PSDrive', 'PSProvider')) { continue }
                    if ($p.Name -notmatch '^(ADMIN\$|IPC\$|print\$|[A-Za-z]\$)$') {
                        $nonStdReg += $p.Name
                    }
                }
                $risultato.Evidence = @{ NonStandardShares = $nonStdReg; Source = 'Registry' }
                if ($nonStdReg.Count -eq 0) {
                    $risultato.Status   = 'superato'
                    $risultato.Observed = "No non-standard shared folders found in LanmanServer registry"
                }
                else {
                    $risultato.Status   = 'fallito'
                    $risultato.Observed = "Shared folders detected ($($nonStdReg.Count)): $($nonStdReg -join ', ')"
                }
                return $risultato
            }
        }
        catch { }

        if ($_.Exception.Message -match 'CIM resource|Access is denied|Accesso negato|privilegi|privilege') {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "Insufficient privileges to inspect SMB shares"
            $risultato.Error    = $_.Exception.Message
        }
        else {
            $risultato.Status = 'errore'
            $risultato.Error  = $_.Exception.Message
        }
    }

    return $risultato
}

function Test-FirmaSmbObbligatoria {
    <#
    .SYNOPSIS
        Verifies that mandatory SMB packet signing (RequireSecuritySignature = 1) is enabled
        to mitigate Man-in-the-Middle and NTLM Relay attacks on local networks (HOME-NET-005).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "RequireSecuritySignature = 1 on both SMB Server and Client"
        Evidence = $null
        Error    = $null
    }

    try {
        $chiaveSrv = 'HKLM:\SYSTEM\CurrentControlSet\Services\LanmanServer\Parameters'
        $chiaveWrk = 'HKLM:\SYSTEM\CurrentControlSet\Services\LanmanWorkstation\Parameters'

        $reqSrv = 0
        $reqWrk = 0

        if (Test-Path -LiteralPath $chiaveSrv) {
            $pSrv = Get-ItemProperty -LiteralPath $chiaveSrv -ErrorAction SilentlyContinue
            if ($null -ne $pSrv -and $null -ne $pSrv.PSObject.Properties['RequireSecuritySignature']) {
                $reqSrv = [int]$pSrv.RequireSecuritySignature
            }
        }
        if (Test-Path -LiteralPath $chiaveWrk) {
            $pWrk = Get-ItemProperty -LiteralPath $chiaveWrk -ErrorAction SilentlyContinue
            if ($null -ne $pWrk -and $null -ne $pWrk.PSObject.Properties['RequireSecuritySignature']) {
                $reqWrk = [int]$pWrk.RequireSecuritySignature
            }
        }

        $risultato.Evidence = @{
            ServerRequireSecuritySignature      = $reqSrv
            WorkstationRequireSecuritySignature = $reqWrk
        }

        if ($reqSrv -eq 1 -and $reqWrk -eq 1) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "Mandatory SMB signing enabled on Server and Client (1)"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "SMB signing not enforced (Server=$reqSrv, Client=$reqWrk)"
        }
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

function Test-WinRmDisabilitatoOSicuro {
    <#
    .SYNOPSIS
        Verifies that the Windows Remote Management (WinRM / PowerShell Remoting) service is stopped
        so remote management ports 5985/5986 are not exposed (HOME-NET-006).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "WinRM service stopped"
        Evidence = $null
        Error    = $null
    }

    try {
        $srv = Get-Service -Name 'WinRM' -ErrorAction SilentlyContinue
        if ($null -eq $srv) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "WinRM service not present"
            return $risultato
        }

        $statoSrv = [string]$srv.Status
        $risultato.Evidence = @{
            ServiceName = 'WinRM'
            Status      = $statoSrv
        }

        if ($statoSrv -ne 'Running') {
            $risultato.Status   = 'superato'
            $risultato.Observed = "WinRM service stopped ($statoSrv)"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "WinRM service is running (remote port 5985 active)"
        }
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

function Test-WpadDisabilitato {
    <#
    .SYNOPSIS
        Verifies that Web Proxy Auto-Discovery (WPAD) is disabled to prevent
        web traffic interception attacks on local/Wi-Fi networks (HOME-NET-007).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "DisableWpad = 1 or WinHttpAutoProxySvc service disabled"
        Evidence = $null
        Error    = $null
    }

    try {
        $chiaveWpad = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Internet Settings\Wpad'
        $disableWpad = 0
        if (Test-Path -LiteralPath $chiaveWpad) {
            $propWpad = Get-ItemProperty -LiteralPath $chiaveWpad -ErrorAction SilentlyContinue
            if ($null -ne $propWpad -and $null -ne $propWpad.PSObject.Properties['DisableWpad']) {
                $disableWpad = [int]$propWpad.DisableWpad
            }
        }

        $chiaveSvc = 'HKLM:\SYSTEM\CurrentControlSet\Services\WinHttpAutoProxySvc'
        $startSvc = 3
        if (Test-Path -LiteralPath $chiaveSvc) {
            $propSvc = Get-ItemProperty -LiteralPath $chiaveSvc -ErrorAction SilentlyContinue
            if ($null -ne $propSvc -and $null -ne $propSvc.PSObject.Properties['Start']) {
                $startSvc = [int]$propSvc.Start
            }
        }

        $risultato.Evidence = @{
            DisableWpad           = $disableWpad
            WinHttpAutoProxyStart = $startSvc
        }

        if ($disableWpad -eq 1 -or $startSvc -eq 4) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "WPAD disabled (DisableWpad=$disableWpad, ServiceStart=$startSvc)"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "WPAD active (DisableWpad=$disableWpad, ServiceStart=$startSvc)"
        }
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

function Test-LegacyTlsAndDoh {
    <#
    .SYNOPSIS
        Verifies that deprecated TLS 1.0 and TLS 1.1 protocols are not enabled in SCHANNEL
        and checks DNS over HTTPS (DoH) support (HOME-NET-008).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "TLS 1.0/1.1 not enabled (Enabled != 1) and DNS over HTTPS (DoH) support present"
        Evidence = $null
        Error    = $null
    }

    try {
        $baseSchannel = 'HKLM:\SYSTEM\CurrentControlSet\Control\SecurityProviders\SCHANNEL\Protocols'
        $sottoChiaviTls = @(
            'TLS 1.0\Client',
            'TLS 1.0\Server',
            'TLS 1.1\Client',
            'TLS 1.1\Server'
        )

        $tlsLegacyAttivi = @()
        foreach ($sub in $sottoChiaviTls) {
            $percorsoTls = Join-Path $baseSchannel $sub
            if (Test-Path -LiteralPath $percorsoTls -ErrorAction SilentlyContinue) {
                $propTls = Get-ItemProperty -LiteralPath $percorsoTls -ErrorAction SilentlyContinue
                if ($null -ne $propTls -and $null -ne $propTls.PSObject.Properties['Enabled'] -and $null -ne $propTls.Enabled) {
                    $valEn = [int]$propTls.Enabled
                    if ($valEn -eq 1) {
                        $tlsLegacyAttivi += "$sub (Enabled=1)"
                    }
                }
            }
        }

        # Check DNS over HTTPS (DoH) configuration
        $chiaveDnsCache = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
        $autoDoh = 0
        if (Test-Path -LiteralPath $chiaveDnsCache -ErrorAction SilentlyContinue) {
            $propDns = Get-ItemProperty -LiteralPath $chiaveDnsCache -ErrorAction SilentlyContinue
            if ($null -ne $propDns -and $null -ne $propDns.PSObject.Properties['EnableAutoDoh'] -and $null -ne $propDns.EnableAutoDoh) {
                $autoDoh = [int]$propDns.EnableAutoDoh
            }
        }

        $dohServerCount = 0
        try {
            if (Get-Command -Name 'Get-DnsClientDohServerAddress' -ErrorAction SilentlyContinue) {
                $dohServers = @(Get-DnsClientDohServerAddress -ErrorAction SilentlyContinue)
                $dohServerCount = $dohServers.Count
            }
        }
        catch { }

        $dohConfigurato = ($autoDoh -ge 1) -or ($dohServerCount -gt 0)

        $risultato.Evidence = @{
            LegacyTlsEnabled = $tlsLegacyAttivi
            EnableAutoDoh    = $autoDoh
            DohServersCount  = $dohServerCount
            DohConfigured    = $dohConfigurato
        }

        if ($tlsLegacyAttivi.Count -gt 0) {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Legacy cryptographic protocols enabled: $($tlsLegacyAttivi -join ', ')"
        }
        elseif (-not $dohConfigurato) {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "TLS 1.0/1.1 disabled, but DNS over HTTPS (DoH) is not configured (EnableAutoDoh=$autoDoh)"
        }
        else {
            $risultato.Status   = 'superato'
            $risultato.Observed = "TLS 1.0/1.1 disabled and DNS over HTTPS (DoH) support active (EnableAutoDoh=$autoDoh, DohServers=$dohServerCount)"
        }
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

# =============================================================================
# MODULE: src\core\Checks\SystemSecurity.ps1
# =============================================================================
<#
.SYNOPSIS
    System security controls: Windows Update, BitLocker, Telemetry, Secure Boot,
    LSA Protection, PowerShell Script Block Logging, Smart App Control, TPM 2.0,
    WSH, ExecutionPolicy, Administrator Protection, and Windows hardening settings.

.DESCRIPTION
    Implements read-only checks for:
    - HOME-UPD-001: Automatic Windows Updates enabled (Test-WindowsUpdateEnabled)
    - HOME-UPD-002: Official Windows Update server (Test-WindowsUpdateAuthenticServer)
    - HOME-ENC-001: BitLocker or Device Encryption active on system drive (Test-BitLockerSystemDrive)
    - HOME-PRV-001: Telemetry set to minimum level (Test-TelemetryMinimum)
    - HOME-SEC-001: UEFI Secure Boot active (Test-SecureBoot)
    - HOME-SEC-002: LSA Protection enabled RunAsPPL (Test-LsaProtection)
    - HOME-SEC-003: PowerShell Script Block Logging enabled (Test-PsScriptBlockLogging)
    - HOME-SYS-001: Known file extensions visible in File Explorer (Test-FileExtensionsVisible)
    - HOME-SYS-002: AutoRun / AutoPlay disabled for removable drives (Test-AutorunDisabled)
    - HOME-SYS-003: Microsoft Defender SmartScreen active (Test-SmartScreenEnabled)
    - HOME-SYS-004: Core Isolation / Memory Integrity HVCI active (Test-MemoryIntegrityEnabled)
    - HOME-SYS-005: Anonymous SAM enumeration restricted (Test-AnonymousSamRestricted)
    - HOME-SYS-006: WDigest cleartext credential caching disabled (Test-WDigestDisabilitato)
    - HOME-SYS-007: Windows Remote Assistance disabled (Test-AssistenzaRemotaDisabilitata)
    - HOME-SYS-008: Remote Registry service disabled (Test-RegistroRemotoDisabilitato)
    - HOME-UAC-002: UAC prompts for elevation on Secure Desktop (Test-UacSecureElevation)
    - HOME-SEC-007: Smart App Control active (Test-SmartAppControl)
    - HOME-SEC-008: Hardware TPM 2.0 present and ready (Test-Tpm20Ready)
    - HOME-SYS-009: Windows Script Host disabled (Test-WshDisabled)
    - HOME-SEC-009: Secure PowerShell ExecutionPolicy (Test-PowerShellExecutionPolicySecure)
    - HOME-UAC-004: Windows 11 Administrator Protection active (Test-AdministratorProtection)
    - HOME-SEC-010: Windows Event Log integrity & Security log clearing check (Test-EventLogIntegrity)
    - HOME-SYS-010: PrintNightmare driver installation protection (Test-PrintNightmareProtection)
    - HOME-SEC-011: Kernel DMA Protection (Test-KernelDmaProtection)
    Never modifies system state.
#>

Set-StrictMode -Version 2

function Test-WindowsUpdateEnabled {
    <#
    .SYNOPSIS
        Verifies that the Windows Update service is not disabled and Group Policy
        does not disable automatic updates.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "wuauserv service enabled (Start != 4) and NoAutoUpdate policy != 1"
        Evidence = $null
        Error    = $null
    }

    try {
        $percorsoServizio = 'HKLM:\SYSTEM\CurrentControlSet\Services\wuauserv'
        $percorsoPolicyAu = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU'

        if (-not (Test-Path -LiteralPath $percorsoServizio)) {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "wuauserv service registry key not found"
            return $risultato
        }

        $propSvc = Get-ItemProperty -LiteralPath $percorsoServizio -ErrorAction Stop
        $startVal = if ($null -ne $propSvc.PSObject.Properties['Start']) { [int]$propSvc.Start } else { 3 }

        $noAutoUpdate = 0
        if (Test-Path -LiteralPath $percorsoPolicyAu) {
            $propAu = Get-ItemProperty -LiteralPath $percorsoPolicyAu -ErrorAction SilentlyContinue
            if ($null -ne $propAu -and $null -ne $propAu.PSObject.Properties['NoAutoUpdate'] -and $null -ne $propAu.NoAutoUpdate) {
                $noAutoUpdate = [int]$propAu.NoAutoUpdate
            }
        }

        $risultato.Evidence = @{
            WuauservStart = $startVal
            NoAutoUpdate  = $noAutoUpdate
        }

        if ($startVal -eq 4) {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Windows Update service (wuauserv) is disabled (Start = 4)"
        }
        elseif ($noAutoUpdate -eq 1) {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Automatic updates are disabled via policy (NoAutoUpdate = 1)"
        }
        else {
            $risultato.Status   = 'superato'
            $risultato.Observed = "Windows Update enabled (wuauserv Start = $startVal, NoAutoUpdate = $noAutoUpdate)"
        }
    }
    catch [System.Security.SecurityException] {
        $risultato.Status   = 'sconosciuto'
        $risultato.Observed = "Access denied to Windows Update configuration"
        $risultato.Error    = $_.Exception.Message
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

function Test-BitLockerSystemDrive {
    <#
    .SYNOPSIS
        Verifies that BitLocker or Device Encryption is active on the system drive.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "BitLocker or Device Encryption active on the system drive"
        Evidence = $null
        Error    = $null
    }

    $discoSistema = if ($env:SystemDrive) { $env:SystemDrive } else { 'C:' }

    try {
        if (Get-Command -Name 'Get-BitLockerVolume' -ErrorAction SilentlyContinue) {
            try {
                $vol = Get-BitLockerVolume -MountPoint $discoSistema -ErrorAction Stop
                $statoProt = [string]$vol.ProtectionStatus
                $statoVol  = [string]$vol.VolumeStatus

                $risultato.Evidence = @{
                    MountPoint       = $discoSistema
                    ProtectionStatus = $statoProt
                    VolumeStatus     = $statoVol
                    Source           = 'Get-BitLockerVolume'
                }

                if ($statoProt -eq 'On' -or $statoProt -eq '1') {
                    $risultato.Status   = 'superato'
                    $risultato.Observed = "BitLocker active on $discoSistema (ProtectionStatus = $statoProt)"
                }
                else {
                    $risultato.Status   = 'fallito'
                    $risultato.Observed = "BitLocker not active on $discoSistema (ProtectionStatus = $statoProt, VolumeStatus = $statoVol)"
                }
                return $risultato
            }
            catch { }
        }

        $percorsoBl = 'HKLM:\SYSTEM\CurrentControlSet\Control\BitLockerStatus'
        if (Test-Path -LiteralPath $percorsoBl) {
            $propBl = Get-ItemProperty -LiteralPath $percorsoBl -ErrorAction Stop
            if ($null -ne $propBl.PSObject.Properties['BootStatus'] -and $null -ne $propBl.BootStatus) {
                $bootStatus = [int]$propBl.BootStatus
                $risultato.Evidence = @{
                    MountPoint = $discoSistema
                    BootStatus = $bootStatus
                    Source     = 'BitLockerStatusRegistry'
                }
                if ($bootStatus -ge 1) {
                    $risultato.Status   = 'superato'
                    $risultato.Observed = "Boot drive encryption active (BootStatus = $bootStatus)"
                }
                else {
                    $risultato.Status   = 'fallito'
                    $risultato.Observed = "BitLocker encryption not active on system drive (BootStatus = 0)"
                }
                return $risultato
            }
        }

        $risultato.Status   = 'sconosciuto'
        $risultato.Observed = "Unable to determine BitLocker status (run as Administrator)"
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

function Test-TelemetryMinimum {
    <#
    .SYNOPSIS
        Verifies that Windows telemetry level (AllowTelemetry) is set to minimum (<= 1).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "AllowTelemetry <= 1 (Required diagnostic data / minimum)"
        Evidence = $null
        Error    = $null
    }

    try {
        $percorsoPolicy  = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection'
        $percorsoDefault = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\DataCollection'

        $valoreTrovato = $null
        $chiaveUsata   = $null

        if (Test-Path -LiteralPath $percorsoPolicy) {
            $propPol = Get-ItemProperty -LiteralPath $percorsoPolicy -ErrorAction SilentlyContinue
            if ($null -ne $propPol -and $null -ne $propPol.PSObject.Properties['AllowTelemetry'] -and $null -ne $propPol.AllowTelemetry) {
                $valoreTrovato = [int]$propPol.AllowTelemetry
                $chiaveUsata   = $percorsoPolicy
            }
        }

        if ($null -eq $valoreTrovato -and (Test-Path -LiteralPath $percorsoDefault)) {
            $propDef = Get-ItemProperty -LiteralPath $percorsoDefault -ErrorAction SilentlyContinue
            if ($null -ne $propDef -and $null -ne $propDef.PSObject.Properties['AllowTelemetry'] -and $null -ne $propDef.AllowTelemetry) {
                $valoreTrovato = [int]$propDef.AllowTelemetry
                $chiaveUsata   = $percorsoDefault
            }
        }

        if ($null -eq $valoreTrovato) {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "AllowTelemetry not restricted (default full telemetry level active)"
            $risultato.Evidence = @{ Configured = $false }
            return $risultato
        }

        $risultato.Evidence = @{
            Path           = $chiaveUsata
            AllowTelemetry = $valoreTrovato
        }

        if ($valoreTrovato -le 1) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "AllowTelemetry = $valoreTrovato (minimum level)"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "AllowTelemetry = $valoreTrovato (above minimum level 1)"
        }
    }
    catch [System.Security.SecurityException] {
        $risultato.Status   = 'sconosciuto'
        $risultato.Observed = "Access denied to DataCollection registry key"
        $risultato.Error    = $_.Exception.Message
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

function Test-SecureBoot {
    <#
    .SYNOPSIS
        Verifies that UEFI Secure Boot is enabled.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "UEFISecureBootEnabled = 1 (Secure Boot enabled)"
        Evidence = $null
        Error    = $null
    }

    try {
        $percorsoSb = 'HKLM:\SYSTEM\CurrentControlSet\Control\SecureBoot\State'
        if (-not (Test-Path -LiteralPath $percorsoSb)) {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "Secure Boot state key not present (possible legacy BIOS system)"
            $risultato.Evidence = @{ KeyExists = $false }
            return $risultato
        }

        $propSb = Get-ItemProperty -LiteralPath $percorsoSb -ErrorAction Stop
        if ($null -eq $propSb.PSObject.Properties['UEFISecureBootEnabled']) {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "UEFISecureBootEnabled value not found"
            return $risultato
        }

        $sbVal = [int]$propSb.UEFISecureBootEnabled
        $risultato.Evidence = @{
            Path                  = $percorsoSb
            UEFISecureBootEnabled = $sbVal
        }

        if ($sbVal -eq 1) {
            $risultato.Status   = 'superato'
            $risultato.Observed = "Secure Boot enabled (UEFISecureBootEnabled = 1)"
        }
        else {
            $risultato.Status   = 'fallito'
            $risultato.Observed = "Secure Boot disabled (UEFISecureBootEnabled = $sbVal)"
        }
    }
    catch [System.Security.SecurityException] {
        $risultato.Status   = 'sconosciuto'
        $risultato.Observed = "Access denied to SecureBoot registry key"
        $risultato.Error    = $_.Exception.Message
    }
    catch {
        $risultato.Status = 'errore'
        $risultato.Error  = $_.Exception.Message
    }

    return $risultato
}

function Test-LsaProtection {
    <#
    .SYNOPSIS
        Verifies that Local Security Authority (LSA) Protection (RunAsPPL) is enabled.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [PSCustomObject]$Controllo,

        [Parameter(Mandatory = $false)]
        [PSCustomObject]$Ambiente = $null
    )

    $risultato = [PSCustomObject]@{
        Status   = 'sconosciuto'
        Observed = $null
        Expected = "RunAsPPL >= 1 or RunAsPPLBoot >= 1 in HKLM:\SYSTEM\CurrentControlSet\Control\Lsa"
        Evidence = $null
        Error    = $null
    }

    try {
        $percorsoLsa = 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa'
        if (-not (Test-Path -LiteralPath $percorsoLsa)) {
            $risultato.Status   = 'sconosciuto'
            $risultato.Observed = "LSA registry key not found"
            return $risultato
        }

        $propLsa = Get-ItemProperty -LiteralPath $percorsoLsa -ErrorAction Stop
        $runAsPpl = if ($null -ne $propLsa.PSObject.Properties['RunAsPPL'] -and $null -ne $propLsa.RunAsPPL) {
            [int]$propLsa.RunAsPPL
        }
        else {
            0
        }

